    Text = "Эх, говоря на минутку, сейчас Кастор все еще в тяжелом состоянии"
  },
  AvgVideoCaption_117618_Content_38 = {
    Text = "Чтобы скорее искупить грехи твоего брата"
  },
  AvgVideoCaption_117618_Content_39 = {
    Text = "Ты тоже должен скорее принять на себя обязанности святого сына"
  },
  AvgVideoCaption_117618_Content_4 = {Text = "Да......"},
  AvgVideoCaption_117618_Content_40 = {
    Text = "…… Извините, мой светильщик, я научусь"
  },
  AvgVideoCaption_117618_Content_41 = {
    Text = "Хорошо, так следуй за мной, внимательно произноси священное деяние держателя света"
  },
  AvgVideoCaption_117618_Content_42 = {
    Text = "Прочувствуйте учения, которые Он даровал"
  },
  AvgVideoCaption_117618_Content_43 = {
    Text = "…… Да, мой светильщик"
  },
  AvgVideoCaption_117618_Content_44 = {
    Text = "«Он держал неугасимый Искра, блуждая по тёмной земле.»"
  },
  AvgVideoCaption_117618_Content_45 = {
    Text = "«Он держал неугасимый Искра, блуждая по тёмной земле.»"
  },
  AvgVideoCaption_117618_Content_46 = {
    Text = "«Он взглянул на полное злодеяний, проливая печальные слёзы.»"
  },
  AvgVideoCaption_117618_Content_47 = {
    Text = "«И тогда Он разорвал кровавую плоть и истек чёрной кровью……»"
  },
  AvgVideoCaption_117618_Content_48 = {
    Text = "«Он взглянул на полное злодеяний, проливая печальные слёзы.»"
  },
  AvgVideoCaption_117618_Content_49 = {
    Text = "«И тогда Он разорвал кровавую плоть и истек чёрной кровью……»"
