  },
  AvgVideoCaption_117618_Content_56 = {
    Text = "В голове образ брата, почему он стал несколько размытым…"
  },
  AvgVideoCaption_117618_Content_57 = {
    Text = "Запиши это, запомни... нет, нельзя использовать бумагу, это будет обнаружено..."
  },
  AvgVideoCaption_117618_Content_58 = {
    Text = "Да, запиши, запиши в укромном месте…"
  },
  AvgVideoCaption_117618_Content_59 = {
    Text = "Запечатано под кроватью! Они не найдут это место..."
  },
  AvgVideoCaption_117618_Content_6 = {
    Text = "Вам должно быть известно, что такой тупой парень, как кастор, не мог бы иметь таких мыслей"
  },
  AvgVideoCaption_117618_Content_60 = {
    Text = "Запишите все, что мы имели с момента рождения, все наши планы побега, все маршруты, которые мы исследовали!"
  },
  AvgVideoCaption_117618_Content_61 = {
    Text = "Если ты хочешь отнять у меня мою волю, ты не сможешь этого сделать!"
  },
  AvgVideoCaption_117618_Content_62 = {
    Text = "Подожди меня, брат, я обязательно найду возможность снова спасти тебя..."
  },
  AvgVideoCaption_117618_Content_63 = {
    Text = "Сегодня мы продолжим читать священное дело держателя фонарей"
