  AvgVideoCaption_117618_Content_64 = {
    Text = "…… Да, мой светильщик"
  },
  AvgVideoCaption_117618_Content_65 = {
    Text = "«Его кровь унесла грехи, освобождая душу от всех грехов.»"
  },
  AvgVideoCaption_117618_Content_66 = {
    Text = "«Его кровь унесла грехи, освобождая душу от всех грехов.»"
  },
  AvgVideoCaption_117618_Content_67 = {
    Text = "«Но мир всё ещё окутан бесконечным мраком, »"
  },
  AvgVideoCaption_117618_Content_68 = {
    Text = "«И затем Он зажёг своим светом собственное тело……»"
  },
  AvgVideoCaption_117618_Content_69 = {
    Text = "«Но мир всё ещё окутан бесконечным мраком, »"
  },
  AvgVideoCaption_117618_Content_7 = {
    Text = "Хорошо, очень хорошо, мечтающие о небе птицы, какая трогательная история"
  },
  AvgVideoCaption_117618_Content_70 = {
    Text = "«И затем Он зажёг своим светом собственное тело……»"
  },
  AvgVideoCaption_117618_Content_71 = {
    Text = "Свечи? Хо Фэн ты их взял?"
  },
  AvgVideoCaption_117618_Content_72 = {
    Text = "Хей-хей, я конечно же самый крутой!"
  },
  AvgVideoCaption_117618_Content_73 = {
    Text = "Так мы сможем ночью тайком читать этот рукописный текст"
  },
  AvgVideoCaption_117618_Content_74 = {
    Text = "Мы прячемся, чтобы нас не поймали..."
  },
  AvgVideoCaption_117618_Content_75 = {
    Text = "Ха... вставай, нужно продолжать резать, запечатлеть наши воспоминания..."
  },
  AvgVideoCaption_117618_Content_76 = {
    Text = "На каком этапе мы остановились, на том моменте, когда мы впервые тайком учились летать"
  },
  AvgVideoCaption_117618_Content_77 = {
    Text = "А потом улетело…… а потом улетело куда?"
  },
  AvgVideoCaption_117618_Content_78 = {
    Text = "Поллукс! Бесполезный ум, вспомни, быстро вспомни"
