  AvgVideoCaption_117618_Content_98 = {
    Text = "Не здесь, не здесь..."
  },
  AvgVideoCaption_117618_Content_99 = {
    Text = "Да, да, под кроватью…"
  },
  AvgVideoCaption_117956_Content_1 = {
    Text = "Дай мне взглянуть"
  },
  AvgVideoCaption_117956_Content_10 = {
    Text = "Эй! Ребенок, стой!"
  },
  AvgVideoCaption_117956_Content_100 = {
    Text = "Не ветер, но очень легкий, очень близкий, всё ближе и ближе"
  },
  AvgVideoCaption_117956_Content_101 = {
    Text = "Как будто кто-то ползет, медленно приближаясь к вашей двери"
  },
  AvgVideoCaption_117956_Content_102 = {
    Text = "Тук-тук-тук. Кто-то стучится в твою Ворота!"
  },
  AvgVideoCaption_117956_Content_103 = {
    Text = "Ты напуган и свернулся в одеяле, дрожишь, притворяясь, что тебя нет"
  },
  AvgVideoCaption_117956_Content_104 = {
    Text = "Скоро стук в Ворота прекратился"
  },
  AvgVideoCaption_117956_Content_105 = {
    Text = "В комнате осталась лишь Тишь, такая Тишь, что она заставляет вас нервничать"
  },
  AvgVideoCaption_117956_Content_106 = {
    Text = "Ты не можешь удержаться и выглядываешь из-за одеяла..."
  },
  AvgVideoCaption_117956_Content_107 = {
    Text = "Дверь приоткрыта!"
  },
  AvgVideoCaption_117956_Content_108 = {
    Text = "Ты опустил голову, и Чёрная Чёрная тень, чернее тьмы, лежит у твоей кровати!"
  },
  AvgVideoCaption_117956_Content_109 = {
    Text = "Ты хочешь закричать, но уже слишком поздно"
