  AvgVideoCaption_117956_Content_11 = {
    Text = "Эй, дайте мне немного тех тыквенных конфет, которые вы только что забрали!"
  },
  AvgVideoCaption_117956_Content_110 = {
    Text = "Две ледяные руки Эдди уже схватили вас за щиколотку"
