  AvgVideoCaption_117956_Content_111 = {
    Text = "Он бросился на тебя, так же быстро, как черная молния!"
  },
  AvgVideoCaption_117956_Content_112 = {
    Text = "Ты это чувствуешь? Этот запах пыли, плесени"
  },
  AvgVideoCaption_117956_Content_113 = {
    Text = "И все ещё есть чуть сладкий, приторный вкус конфет!"
  },
  AvgVideoCaption_117956_Content_114 = {
    Text = "Руки Эдди резко потянулись к месту, где ты прятал сладости!"
  },
  AvgVideoCaption_117956_Content_115 = {
    Text = "Под подушкой! В рюкзаке! Независимо от того, как хорошо ты спрятал!"
  },
  AvgVideoCaption_117956_Content_116 = {
    Text = "Хруст, чавк, он ест! Безумно ест!"
  },
  AvgVideoCaption_117956_Content_117 = {
    Text = "Твой шоколад! Твои мягкие конфеты! Твои леденцы!"
  },
  AvgVideoCaption_117956_Content_118 = {
    Text = "Ни одна не будет упущена! Этот звук словно жует кости!"
  },
  AvgVideoCaption_117956_Content_119 = {
    Text = "Ты думаешь, он уйдет после того, как съест конфеты?"
  },
  AvgVideoCaption_117956_Content_12 = {
    Text = "Почему? По праву моего благородного..."
  },
  AvgVideoCaption_117956_Content_120 = {
    Text = "Нет, его жажда... только что была пробуждена!"
  },
  AvgVideoCaption_117956_Content_121 = {
    Text = "«Недостаточно, недостаточно…… нужно больше сладкого, самого сладкого……»"
  },
  AvgVideoCaption_117956_Content_122 = {
    Text = "Жадный взор Эдди пристально следит за тобой"
  },
  AvgVideoCaption_117956_Content_123 = {
    Text = "Та холодная рука, с тягучесть сиропа, потянулась к твоему лицу!"
  },
  AvgVideoCaption_117956_Content_124 = {
    Text = "Его пальцы коснулись твоих век, пфью!"
  },
  AvgVideoCaption_117956_Content_125 = {
    Text = "Он забрал то, что считал наиболее похожим на конфету, кругленьким и все еще теплым..."
