  AvgVideoCaption_117956_Content_128 = {
    Text = "Он нашел то, что считал самым сладким «медом»"
  },
  AvgVideoCaption_117956_Content_129 = {
    Text = "Просто прячется в вашем черепе..."
  },
  AvgVideoCaption_117956_Content_13 = {
    Text = "Эй! Не уходите! Неприличные маленькие черти!!"
