  AvgVideoCaption_117956_Content_130 = {
    Text = "На следующее утро люди вас найдут"
  },
  AvgVideoCaption_117956_Content_131 = {
    Text = "На лице, где раньше были глаза, останется только два пустых черных отверстия"
