  },
  AvgVideoCaption_117956_Content_24 = {
    Text = "История этого голодного духа…"
  },
  AvgVideoCaption_117956_Content_25 = {
    Text = "Давным-давно —"
  },
  AvgVideoCaption_117956_Content_26 = {
    Text = "Вероятно, когда ваши прапрадеды были еще маленькими мальчиками"
  },
  AvgVideoCaption_117956_Content_27 = {
    Text = "На земле Митхага когда-то был человек по имени Эдди..."
  },
  AvgVideoCaption_117956_Content_28 = {
    Text = "Да, студент Эдди Хопа"
  },
  AvgVideoCaption_117956_Content_29 = {
    Text = "Несчастный Эдди — хилый Мальчик"
  },
  AvgVideoCaption_117956_Content_3 = {
    Text = "Вот оно и есть!"
  },
  AvgVideoCaption_117956_Content_30 = {
    Text = "Та старая школьная форма висела на нём пусто"
  },
  AvgVideoCaption_117956_Content_31 = {
    Text = "Как на пшеничном поле, сделанном из сухих веток"
  },
  AvgVideoCaption_117956_Content_32 = {
    Text = "Почему он так худ?"
  },
  AvgVideoCaption_117956_Content_33 = {
    Text = "Эмм, потому что Эдди — Сирота"
  },
  AvgVideoCaption_117956_Content_34 = {
    Text = "А в то время Митхаг, конечно, был маленьким и бедным, и всем было нормально не наедаться!"
  },
  AvgVideoCaption_117956_Content_35 = {
    Text = "Все это не важно, в общем"
  },
  AvgVideoCaption_117956_Content_36 = {
    Text = "Эдди не любит говорить, он всегда один, один делает все эти опасные выездные задания"
  },
  AvgVideoCaption_117956_Content_37 = {
    Text = "К сожалению, он очень быстро заразился ужасной болезнью"
  },
  AvgVideoCaption_117956_Content_38 = {
    Text = "Его плоть постепенно разъедалась черным слизи, и на лице появились дыры"
  },
  AvgVideoCaption_117956_Content_39 = {
    Text = "Иногда, по несчастью, бах!"
  },
  AvgVideoCaption_117956_Content_4 = {
    Text = "Что? Почему снова группа детей?"
  },
  AvgVideoCaption_117956_Content_40 = {
    Text = "Одна шкура может свалиться так, что висит прямо на его лице..."
  },
  AvgVideoCaption_117956_Content_41 = {
    Text = "Не только это, он постепенно осознаёт, что его окружающие начинают его забывать"
  },
  AvgVideoCaption_117956_Content_42 = {
    Text = "Никто не помнит об этом общежитии"
  },
  AvgVideoCaption_117956_Content_43 = {
    Text = "И ещё одно бедное создание, которое слегло с болезни"
  },
  AvgVideoCaption_117956_Content_44 = {
    Text = "Наконец, Эдди становится настолько слаб, что не может даже поесть"
  },
  AvgVideoCaption_117956_Content_45 = {
    Text = "Вода тоже не имеет сил, чтобы пить"
  },
  AvgVideoCaption_117956_Content_46 = {
    Text = "Он голоден, как будто живот прижался к спине, а горло пересохло, как будто горит"
  },
  AvgVideoCaption_117956_Content_47 = {
    Text = "Но может только стонать в постели"
  },
  AvgVideoCaption_117956_Content_48 = {
    Text = "Какое отношение имеет эта история к призраку конфет?"
  },
  AvgVideoCaption_117956_Content_49 = {
    Text = "Не торопись, просто слушай, и всё станет понятно"
  },
  AvgVideoCaption_117956_Content_5 = {
    Text = "Университет митхага так много семейных членов в школе?"
  },
  AvgVideoCaption_117956_Content_50 = {
    Text = "На ночь всех святых"
  },
  AvgVideoCaption_117956_Content_51 = {
    Text = "Вдруг он услышал смутный смех снизу"
  },
  AvgVideoCaption_117956_Content_52 = {
    Text = "Дети кричат: «Конфеты или шалости!»"
  },
  AvgVideoCaption_117956_Content_53 = {
    Text = "Один за другим пробегают мимо его окна"
  },
  AvgVideoCaption_117956_Content_54 = {
    Text = "Это радостный смех, еле уловимый аромат ириса"
  },
  AvgVideoCaption_117956_Content_55 = {
    Text = "Как злая лапа, она царапает и щиплет его грудь"
  },
  AvgVideoCaption_117956_Content_56 = {
    Text = "Почему, почему я был забыт?"
  },
  AvgVideoCaption_117956_Content_57 = {
    Text = "Почему никто не заботится о себе?"
  },
  AvgVideoCaption_117956_Content_58 = {
    Text = "Забываемый Страх и боль от болезни терзали его"
  },
  AvgVideoCaption_117956_Content_59 = {
    Text = "Вдруг, колоссальное желание окончательно сломило его"
  },
  AvgVideoCaption_117956_Content_6 = {
    Text = "Поспешите, поспешите..."
  },
  AvgVideoCaption_117956_Content_60 = {
    Text = "Он принял решение, безумное решение, решение в отчаянии"
  },
  AvgVideoCaption_117956_Content_61 = {
    Text = "Он хочет найти конфету, лишь одну!"
  },
  AvgVideoCaption_117956_Content_62 = {
    Text = "Если сегодня ночью я умру, то непременно сделаю это, наслаждаясь сладким послевкусием"
  },
  AvgVideoCaption_117956_Content_63 = {
    Text = "Эдди изо всех сил спустился с кровати, он оперся на пол обеими руками"
  },
  AvgVideoCaption_117956_Content_64 = {
    Text = "Медленно, медленно двигаясь вперёд..."
  },
  AvgVideoCaption_117956_Content_65 = {
    Text = "Он открыл тонкую Ворота комнаты"
  },
  AvgVideoCaption_117956_Content_66 = {
    Text = "Как Чёрная Чёрная тень, он медленно сползает по черной, ледяной лестнице"
  },
  AvgVideoCaption_117956_Content_67 = {
    Text = "Он полз, полз"
  },
  AvgVideoCaption_117956_Content_68 = {
    Text = "Но он слишком слаб, слишком холоден"
  },
  AvgVideoCaption_117956_Content_69 = {
    Text = "Когда он доберётся до двери общежития, у него не останется сил открыть эту Ворота"
  },
  AvgVideoCaption_117956_Content_7 = {
    Text = "А!! Корзина конфет действительно пустая"
  },
  AvgVideoCaption_117956_Content_70 = {
    Text = "«Кто-нибудь…… помогите мне…… кто-нибудь…… дайте мне конфету……»"
  },
  AvgVideoCaption_117956_Content_71 = {
    Text = "Никто не слышал его голоса, никто не видел его образа"
  },
  AvgVideoCaption_117956_Content_72 = {
    Text = "С одним скрипом, счастливые студенты распахнули двери общежития"
  },
  AvgVideoCaption_117956_Content_73 = {
    Text = "А потом бесчисленное количество обуви топтало его"
  },
  AvgVideoCaption_117956_Content_74 = {
    Text = "Хруст, это был звук сломанной кости Эдди"
  },
  AvgVideoCaption_117956_Content_75 = {
    Text = "Пух, это звук крови Эдди, раздавленной под ногами..."
  },
  AvgVideoCaption_117956_Content_76 = {
    Text = "Отчаянные крики были заглушены радостным смехом"
  },
  AvgVideoCaption_117956_Content_77 = {
    Text = "Пока он не превратился в размазанное пятно, та жаждущая рука всё ещё тянулась к двери…"
  },
  AvgVideoCaption_117956_Content_78 = {
    Text = "Он до самой смерти... не tasted ту конфету в своем сне"
  },
  AvgVideoCaption_117956_Content_79 = {
    Text = "Эдди мёртв"
  },
  AvgVideoCaption_117956_Content_8 = {
    Text = "Эта группа ненавиных саранчей!"
  },
  AvgVideoCaption_117956_Content_80 = {
    Text = "Но его голод... та жажда к конфетам, пронизывающая до глубины души, не умерла"
  },
  AvgVideoCaption_117956_Content_81 = {
    Text = "Он остался, как сироп, липкий, как зимний холодный ветер, пронизывающий до мозга"
  },
  AvgVideoCaption_117956_Content_82 = {
    Text = "Каждый год, когда тыквенные огни зажигаются, а воздух наполняется запахом конфет, Эдди..."
  },
  AvgVideoCaption_117956_Content_83 = {
    Text = "Или же жажда, оставленная Эдди, проснется"
  },
  AvgVideoCaption_117956_Content_84 = {
    Text = "Он больше не тот жалкий Мальчик"
  },
  AvgVideoCaption_117956_Content_85 = {
    Text = "Он стал чем-то другим, более страшным"
  },
  AvgVideoCaption_117956_Content_86 = {
    Text = "Блуждая в тенях этого кампуса"
  },
  AvgVideoCaption_117956_Content_87 = {
    Text = "Он чувствует запах конфет!"
  },
  AvgVideoCaption_117956_Content_88 = {
    Text = "Особенно те сокровища, которые вы положили в корзину, спрятали в карманах рюкзачка и прикрыли в теплых карманах!"
  },
  AvgVideoCaption_117956_Content_89 = {
    Text = "В ночь всех святых, если у вас много конфет, когда вы идете домой"
  },
  AvgVideoCaption_117956_Content_9 = {
    Text = "Нет, я ещё не успел попробовать эти особые тыквенные конфеты"
  },
  AvgVideoCaption_117956_Content_90 = {
    Text = "Ты почувствуешь прохладу на шее, словно кто-то дует холодным дыханием"
  },
  AvgVideoCaption_117956_Content_91 = {
    Text = "Когда вы оглянетесь, вы увидите, что ничего нет"
  },
  AvgVideoCaption_117956_Content_92 = {
    Text = "Только ветер и странные тени……"
  },
  AvgVideoCaption_117956_Content_93 = {
    Text = "Нет, это Эдди следует за тобой!"
  },
  AvgVideoCaption_117956_Content_94 = {
    Text = "Он будет следовать за запахом конфет, тихо идя за тобой"
  },
  AvgVideoCaption_117956_Content_95 = {
    Text = "Ты только унюхаешь легкий запашок, смешанный с пылью и старой одеждой"
  },
  AvgVideoCaption_117956_Content_96 = {
    Text = "До полночь! Когда колокольня пробьёт двенадцать раз"
  },
  AvgVideoCaption_117956_Content_97 = {
    Text = "На кампусе было совершенно тихо, даже совы закрыли свои рты"
  },
  AvgVideoCaption_117956_Content_98 = {
    Text = "В этот момент… вы услышите странный звук у своей двери"
  },
  AvgVideoCaption_117956_Content_99 = {
    Text = "Шш…… шш……"
  },
  AvgVideoCaption_122450_Content_1 = {
    Text = "Выход, Выход там..."
  },
  AvgVideoCaption_122450_Content_10 = {
    Text = "Теперь пусть искажённые кости и кровь сплетутся в судьбу"
  },
  AvgVideoCaption_122450_Content_11 = {
    Text = "Благодаря ложной пуповине"
  },
  AvgVideoCaption_122450_Content_12 = {
    Text = "Пройдите через мои хрупкие двери..."
  },
  AvgVideoCaption_122450_Content_13 = {
    Text = "Пусть я появлюсь на этот мир!"
  },
  AvgVideoCaption_122450_Content_14 = {
    Text = "Смотри, Он открыл глаза!"
  },
  AvgVideoCaption_122450_Content_15 = {
    Text = "Обними меня, мой дорогой"
  },
  AvgVideoCaption_122450_Content_16 = {Text = "Мой.."},
  AvgVideoCaption_122450_Content_17 = {
    Text = "Мой.. отец"
  },
  AvgVideoCaption_122450_Content_18 = {
    Text = "Мой.. отец"
  },
  AvgVideoCaption_122450_Content_19 = {
    Text = "Моя Колесо Судьбы"
  },
  AvgVideoCaption_122450_Content_2 = {
    Text = "Почему нужно уходить?"
  },
  AvgVideoCaption_122450_Content_3 = {
    Text = "Не беспокойтесь, здесь очень безопасно"
  },
  AvgVideoCaption_122450_Content_4 = {
    Text = "Не надо... Я не хочу быть какой-то богиней"
  },
  AvgVideoCaption_122450_Content_5 = {
    Text = "Я дочь бога"
  },
  AvgVideoCaption_122450_Content_6 = {
    Text = "Никто не может противоречить моей воле"
  },
  AvgVideoCaption_122450_Content_7 = {
    Text = "Я это чувствую"
  },
  AvgVideoCaption_122450_Content_8 = {
    Text = "Эта совершенная боль"
  },
  AvgVideoCaption_122450_Content_9 = {
    Text = "И совершенное созревание"
  },
  AvgVideoCaption_122705_Content_1 = {
    Text = "Это история, произошедшая через Часть 7 дней после рождения богов"
  },
  AvgVideoCaption_122705_Content_10 = {
    Text = "Но на лицах всех сияла восторженная радость"
  },
  AvgVideoCaption_122705_Content_100 = {
    Text = "Лежащий на моей груди"
  },
  AvgVideoCaption_122705_Content_101 = {
    Text = "Просто лицемерные образы"
  },
  AvgVideoCaption_122705_Content_102 = {
    Text = "Груда мёртвого мяса, ошибочно называемая «богом»"
  },
  AvgVideoCaption_122705_Content_103 = {
    Text = "Почему?"
  },
  AvgVideoCaption_122705_Content_104 = {
    Text = "Почему эта искажённая, несправедливая Колесо Судьбы не хочет оставить меня в покое?"
  },
  AvgVideoCaption_122705_Content_105 = {
    Text = "Боже, почему ты всё время наказываешь меня?"
  },
  AvgVideoCaption_122705_Content_106 = {Text = "Бог...?"},
  AvgVideoCaption_122705_Content_107 = {
    Text = "Хаха, хаха, я понял!"
  },
  AvgVideoCaption_122705_Content_108 = {
    Text = "Я должен был это понять!"
  },
  AvgVideoCaption_122705_Content_109 = {
    Text = "Ты вовсе не бог, верно?"
  },
  AvgVideoCaption_122705_Content_11 = {
    Text = "Должен ли я чувствовать радость?"
  },
  AvgVideoCaption_122705_Content_110 = {
    Text = "Как Реальность бог может позволить своим последователям упасть до такого безумного состояния?"
  },
  AvgVideoCaption_122705_Content_111 = {
    Text = "Как Реальность бог может быть гнилой кучей испорченного мяса?"
  },
  AvgVideoCaption_122705_Content_112 = {
    Text = "Все меня обманывают. Мириам, так называемая божественность..."
  },
  AvgVideoCaption_122705_Content_113 = {
    Text = "Все обманщики, всё — ложь"
  },
  AvgVideoCaption_122705_Content_114 = {
    Text = "Ха, я прожил так долго во лжи"
  },
  AvgVideoCaption_122705_Content_115 = {
    Text = "Из-за этого куска гнилого мяса я уже заплатил такую большую цену..."
  },
  AvgVideoCaption_122705_Content_116 = {
    Text = "Судьба, Колесо Судьбы — всё это Иллюзия..."
  },
  AvgVideoCaption_122705_Content_117 = {
    Text = "Ты, монстр... почему ты решаешь моё будущее?"
  },
  AvgVideoCaption_122705_Content_118 = {
    Text = "Я отдал всё это не ради тебя!"
  },
  AvgVideoCaption_122705_Content_119 = {
    Text = "Никогда не было!"
  },
  AvgVideoCaption_122705_Content_12 = {
    Text = "Должен ли я радоваться этому?"
  },
  AvgVideoCaption_122705_Content_120 = {
    Text = "Сдохни, отвратительное чудовище!"
  },
  AvgVideoCaption_122705_Content_121 = {
    Text = "Это где?"
  },
  AvgVideoCaption_122705_Content_122 = {
    Text = "Я вернулся... в тот день, когда родился Освящение зародыш?"
  },
  AvgVideoCaption_122705_Content_123 = {
    Text = "Хороший ребёнок, ты совершила славную жертву..."
  },
  AvgVideoCaption_122705_Content_124 = {
    Text = "Хаха, хаха, я вернулся, я снова вернулся!"
  },
  AvgVideoCaption_122705_Content_125 = {
    Text = "Я не могу сбежать, я не могу сбежать!"
  },
  AvgVideoCaption_122705_Content_126 = {
    Text = "Траектория движения звёзд уже запечатлена на куполе"
  },
  AvgVideoCaption_122705_Content_127 = {
    Text = "Каждый развилок ведет к одной и той же бездне..."
  },
  AvgVideoCaption_122705_Content_128 = {
    Text = "Так называемый выбор — это всего лишь..."
  },
  AvgVideoCaption_122705_Content_129 = {
    Text = "Это всего лишь сценарий, который Колесо Судьбы уже написала"
  },
  AvgVideoCaption_122705_Content_13 = {
    Text = "Я тоже не уверен"
  },
  AvgVideoCaption_122705_Content_130 = {
    Text = "Это всего лишь самодовольное импровизированное представление!"
  },
  AvgVideoCaption_122705_Content_131 = {
    Text = "Боже, раз ты настаиваешь на том, чтобы не менять этот абсурдный сценарий..."
  },
  AvgVideoCaption_122705_Content_132 = {
    Text = "Тогда я могу только позволить тебе стать свидетелем"
  },
  AvgVideoCaption_122705_Content_133 = {
    Text = "Всё, что вы задумали"
  },
  AvgVideoCaption_122705_Content_134 = {
    Text = "Как стать лестницей, по которой я наслаждаюсь величием!"
  },
  AvgVideoCaption_122705_Content_14 = {
    Text = "Второй день рождения Бога"
  },
  AvgVideoCaption_122705_Content_15 = {
    Text = "Текст молитвы Матери-богини на освящение святого эмбриона"
  },
  AvgVideoCaption_122705_Content_16 = {
    Text = "Пусть наш Господь простит её грубость и небрежность"
  },
  AvgVideoCaption_122705_Content_17 = {
    Text = "Вы, грязные слуги, отступите!"
  },
  AvgVideoCaption_122705_Content_18 = {
    Text = "Только я имею право увидеть Его истинное лицо"
  },
  AvgVideoCaption_122705_Content_19 = {
    Text = "Я не осмеливаюсь позволить кому-либо увидеть «бога», которого я родила."
  },
  AvgVideoCaption_122705_Content_2 = {
    Text = "Первый день рождения бога"
  },
  AvgVideoCaption_122705_Content_20 = {
    Text = "Тот крещёный «эмбрион» — это хаотичная кровь и плоть, лишённые духовного разума"
  },
  AvgVideoCaption_122705_Content_21 = {
    Text = "Наверняка, это потому что я ещё не достаточно совершенен..."
  },
  AvgVideoCaption_122705_Content_22 = {
    Text = "Нельзя, чтобы кто-то это заметил"
  },
  AvgVideoCaption_122705_Content_23 = {
    Text = "Со временем, когда Бог ответит на мой призыв, всё будет хорошо"
  },
  AvgVideoCaption_122705_Content_24 = {
    Text = "Третий день рождения Бога"
  },
  AvgVideoCaption_122705_Content_25 = {
    Text = "Святой плод всё ещё не открыл глаза"
  },
  AvgVideoCaption_122705_Content_26 = {
    Text = "Боже, когда же ты наконец откроешь глаза?"
  },
  AvgVideoCaption_122705_Content_27 = {
    Text = "Ты ведь обещал(а) Мириам"
  },
  AvgVideoCaption_122705_Content_28 = {
    Text = "Принесёт ли она восстановление божественной страны?"
  },
  AvgVideoCaption_122705_Content_29 = {
    Text = "Четвёртый день рождения бога"
  },
  AvgVideoCaption_122705_Content_3 = {
    Text = "Зародыш бога рождается из обуглившегося тела"
  },
  AvgVideoCaption_122705_Content_30 = {
    Text = "Церемония общения с божеством сегодня проходит в святом храме"
  },
  AvgVideoCaption_122705_Content_31 = {
    Text = "Пожалуйста, даруйте нам славу"
  },
  AvgVideoCaption_122705_Content_32 = {
    Text = "Показать координаты места, где поднимается божественное царство для тех, кто стремится к морю"
  },
  AvgVideoCaption_122705_Content_33 = {
    Text = "Мы с нетерпением ждем вашего возрождения и прибытия"
  },
  AvgVideoCaption_122705_Content_34 = {
    Text = "Я спрашиваю о будущем божественной страны"
  },
  AvgVideoCaption_122705_Content_35 = {
    Text = "Спросите Его о связи между нами"
  },
  AvgVideoCaption_122705_Content_36 = {
    Text = "Спросите меня о том, что хотите знать"
  },
  AvgVideoCaption_122705_Content_37 = {
    Text = "И всё, что Мириам пыталась выяснить"
  },
  AvgVideoCaption_122705_Content_38 = {
    Text = "Бог молчит"
  },
  AvgVideoCaption_122705_Content_39 = {
    Text = "Пятый день рождения Бога"
  },
  AvgVideoCaption_122705_Content_4 = {
    Text = "Время правильной позиции наступило!"
  },
  AvgVideoCaption_122705_Content_40 = {
    Text = "Мириам спросила меня о результатах встречи с богом"
  },
  AvgVideoCaption_122705_Content_41 = {
    Text = "Как дела?"
  },
  AvgVideoCaption_122705_Content_42 = {
    Text = "Уже целых два дня прошло..."
  },
  AvgVideoCaption_122705_Content_43 = {
    Text = "Мой господин..."
  },
  AvgVideoCaption_122705_Content_44 = {
    Text = "Вы слышали его голос?"
  },
  AvgVideoCaption_122705_Content_45 = {
    Text = "Конечно, конечно, услышал!"
  },
  AvgVideoCaption_122705_Content_46 = {
    Text = "Такие сомнения — это неуважение к Богине!"
  },
  AvgVideoCaption_122705_Content_47 = {
    Text = "Морфи, Морфи, мой хороший Морфи"
  },
  AvgVideoCaption_122705_Content_48 = {
    Text = "Какое божественное повеление даровал мой господин?"
  },
  AvgVideoCaption_122705_Content_49 = {
    Text = "Он, он сказал: «Божье царство скоро поднимется»"
  },
  AvgVideoCaption_122705_Content_5 = {
    Text = "Прибытие Божественного"
  },
  AvgVideoCaption_122705_Content_50 = {
    Text = "Как и ожидалось, как и ожидалось!"
  },
  AvgVideoCaption_122705_Content_51 = {
    Text = "Не зря я ждал тысячи моментов правильной позиции звёзд"
  },
  AvgVideoCaption_122705_Content_52 = {
    Text = "Господин, наконец-то вы пришли исполнить своё обещание!"
  },
  AvgVideoCaption_122705_Content_53 = {
    Text = "Так когда же это было?"
  },
  AvgVideoCaption_122705_Content_54 = {
    Text = "В любом случае, божественная страна обязательно явится"
  },
  AvgVideoCaption_122705_Content_55 = {
    Text = "В какой момент это так важно?"
  },
  AvgVideoCaption_122705_Content_56 = {
    Text = "Нет, нет, нет, я обязательно буду купаться в ладанном дыму, с собой возьму все племена"
  },
  AvgVideoCaption_122705_Content_57 = {
    Text = "Отправляйтесь в место восшествия божественной страны и ждите прибытия моего господина."
  },
  AvgVideoCaption_122705_Content_58 = {
    Text = "……«Звёзды сошлись»"
  },
  AvgVideoCaption_122705_Content_59 = {
    Text = "Момент правильного расположения звезд?"
  },
  AvgVideoCaption_122705_Content_6 = {
    Text = "Вы услышали меня, вы ответили мне!"
  },
  AvgVideoCaption_122705_Content_60 = {
    Text = "Какой момент занимает звезда?"
  },
  AvgVideoCaption_122705_Content_61 = {
    Text = "Следующий? Или следующий следующий?"
  },
  AvgVideoCaption_122705_Content_62 = {
    Text = "Как же шумно, я же сказал, это момент правильной позиции звёзд"
  },
  AvgVideoCaption_122705_Content_63 = {
    Text = "Хо Фэн мне знать, какое именно время звезды?"
  },
  AvgVideoCaption_122705_Content_64 = {Text = "Да, да"},
  AvgVideoCaption_122705_Content_65 = {
    Text = "Мой господин только что пробудился от долгого сна"
  },
  AvgVideoCaption_122705_Content_66 = {
    Text = "Сознание все еще находится в хаосе"
  },
  AvgVideoCaption_122705_Content_67 = {
    Text = "Наверняка сейчас тоже всё размыто"
  },
  AvgVideoCaption_122705_Content_68 = {
    Text = "Лишь бы мой господин в конце концов появился..."
  },
  AvgVideoCaption_122705_Content_69 = {
    Text = "Это вообще не важно……"
  },
  AvgVideoCaption_122705_Content_7 = {
    Text = "Ваше волеизъявление скоро будет осуществлено на земле"
  },
  AvgVideoCaption_122705_Content_70 = {
    Text = "Мириам в восторге"
  },
  AvgVideoCaption_122705_Content_71 = {
    Text = "Это была эйфория, которую я никогда не видел"
  },
  AvgVideoCaption_122705_Content_72 = {
    Text = "Я не подарил ей деревянную скульптуру"
  },
  AvgVideoCaption_122705_Content_73 = {
    Text = "Когда я носила священное дитя, тоже не было"
  },
  AvgVideoCaption_122705_Content_74 = {
    Text = "Шестой день рождения Бога"
  },
  AvgVideoCaption_122705_Content_75 = {
    Text = "Яркая аура в моем сердце затянута тенью"
  },
  AvgVideoCaption_122705_Content_76 = {
    Text = "Могу ли я спросить, где же божественная страна снизойдет, мой господин?"
  },
  AvgVideoCaption_122705_Content_77 = {
    Text = "Я отправлю мореплавателя, чтобы он построил алтарь для встречи божественной страны поблизости"
  },
  AvgVideoCaption_122705_Content_78 = {
    Text = "Он сказал, что еще не подумал! В любом случае, он поднимается из-под уровня моря!"
  },
  AvgVideoCaption_122705_Content_79 = {
    Text = "Это... Правда ли так?"
  },
  AvgVideoCaption_122705_Content_8 = {
    Text = "Лемурия будет вечной под вашим руководством!"
  },
  AvgVideoCaption_122705_Content_80 = {
    Text = "Э-э... то, то само собой!"
  },
  AvgVideoCaption_122705_Content_81 = {
    Text = "Слова Богини не могут быть ложными?"
  },
  AvgVideoCaption_122705_Content_82 = {
    Text = "Извините, я слишком торопился"
  },
  AvgVideoCaption_122705_Content_83 = {
    Text = "Я не должен Сомнение в богине"
  },
  AvgVideoCaption_122705_Content_84 = {
    Text = "Лемурия, король того времени"
  },
  AvgVideoCaption_122705_Content_85 = {
    Text = "Также такая же небрежная поза..."
  },
  AvgVideoCaption_122705_Content_86 = {
    Text = "Позвольте мне поцеловать вашу тыльную сторону руки"
  },
  AvgVideoCaption_122705_Content_87 = {
    Text = "Приношу извинения за свое неуважение"
  },
  AvgVideoCaption_122705_Content_88 = {
    Text = "... наконец-то удалось отделаться"
  },
  AvgVideoCaption_122705_Content_89 = {
    Text = "Но что же делать завтра?"
  },
  AvgVideoCaption_122705_Content_9 = {
    Text = "Я изнурён из-за исчерпанной духовной энергии"
  },
  AvgVideoCaption_122705_Content_90 = {
    Text = "Почему боги не отвечают на наши жертвоприношения и молитвы?"
  },
  AvgVideoCaption_122705_Content_91 = {
    Text = "Мириам вовсе не верила мне"
  },
  AvgVideoCaption_122705_Content_92 = {
    Text = "Я могу увидеть это по её взгляду"
  },
  AvgVideoCaption_122705_Content_93 = {
    Text = "Она видела ещё не умерших богов"
  },
  AvgVideoCaption_122705_Content_94 = {
    Text = "Моя ложь не обязательно сработает"
  },
  AvgVideoCaption_122705_Content_95 = {
    Text = "Боже, пожалуйста, спаси меня"
  },
  AvgVideoCaption_122705_Content_96 = {
    Text = "Хотя бы одно слово, ответь на мою молитву"
  },
  AvgVideoCaption_122705_Content_97 = {
    Text = "Седьмой день рождения бога"
  },
  AvgVideoCaption_122705_Content_98 = {
    Text = "Бог уже мёртв"
  },
  AvgVideoCaption_122705_Content_99 = {
    Text = "Бог никогда не рождался"
  },
  AvgVideoCaption_124223_Content_1 = {
    Text = "Что-то говорил детектив..."
  },
  AvgVideoCaption_124223_Content_10 = {
    Text = "А, точно, в туманном бедствии, хотя я внезапно потерял способность видеть «древности»"
  },
  AvgVideoCaption_124223_Content_100 = {
    Text = "Несчастный случай? Ошибка? Или что-то другое?"
  },
  AvgVideoCaption_124223_Content_101 = {
    Text = "Скажи, расскажи мне, почему я здесь!"
  },
  AvgVideoCaption_124223_Content_102 = {
    Text = "Кто и с какой целью привел меня сюда!"
  },
  AvgVideoCaption_124223_Content_103 = {
    Text = "Не скажешь, да? Ничего страшного, всё в порядке, у вас нет рта, я понимаю"
  },
  AvgVideoCaption_124223_Content_104 = {
    Text = "Мне нужно найти человека с губами"
  },
  AvgVideoCaption_124223_Content_105 = {
    Text = "Да, это человек, а не монстр, состоящий из густого тумана"
  },
  AvgVideoCaption_124223_Content_106 = {
    Text = "Мне нужно вернуться, я обязан вернуться"
  },
  AvgVideoCaption_124223_Content_107 = {
    Text = "Это проклятое место... Если я останусь здесь дольше, я с ума сойду..."
  },
  AvgVideoCaption_124223_Content_108 = {
    Text = "Двадцать восьмой день, я нашёл человека"
  },
  AvgVideoCaption_124223_Content_109 = {
    Text = "Я наконец-то понял причину своего «пересечения»"
  },
  AvgVideoCaption_124223_Content_11 = {
    Text = "Но всё равно так тепло, словно вернулся домой"
  },
  AvgVideoCaption_124223_Content_110 = {
    Text = "Та группа сектантов"
  },
  AvgVideoCaption_124223_Content_111 = {
    Text = "Сектанты, которых я увидел, когда «пересек» сюда, призвали меня"
  },
  AvgVideoCaption_124223_Content_112 = {
    Text = "Эти сумасшедшие хотят покинуть это место, чтобы найти этот чертов «новый мир»."
  },
  AvgVideoCaption_124223_Content_113 = {
    Text = "Но наоборот, меня перенесли из «нового мира»"
  },
  AvgVideoCaption_124223_Content_114 = {
    Text = "Ха, это действительно чёрный юмор"
  },
  AvgVideoCaption_124223_Content_115 = {
    Text = "Последователь, я собирался забрать этот отчёт о расследовании, чтобы показать вам"
  },
  AvgVideoCaption_124223_Content_116 = {
    Text = "Но сейчас не нужно"
  },
  AvgVideoCaption_124223_Content_117 = {
    Text = "У меня есть новый план"
  },
  AvgVideoCaption_124223_Content_118 = {
    Text = "Разве они не любят ловить людей?"
  },
  AvgVideoCaption_124223_Content_119 = {
    Text = "Здесь есть один"
  },
  AvgVideoCaption_124223_Content_12 = {
    Text = "Поэтому я вообще не осознавал, что «пересек» себя"
  },
  AvgVideoCaption_124223_Content_120 = {
    Text = "Дай мне подумать, как мне следует выступить..."
  },
  AvgVideoCaption_124223_Content_121 = {
    Text = "Помоги Мне!"
  },
  AvgVideoCaption_124223_Content_122 = {
    Text = "Нет, запаха недостаточно, нужно больше страха, больше отчаяния..."
  },
  AvgVideoCaption_124223_Content_123 = {Text = "Да"},
  AvgVideoCaption_124223_Content_124 = {
    Text = "Как вопли тех выживших в предсмертной агонии"
  },
  AvgVideoCaption_124223_Content_125 = {
    Text = "Теперь «Записи исследований Мося в ином мире» подходят к концу."
  },
  AvgVideoCaption_124223_Content_126 = {
    Text = "На сцену выходит постановка «Невинная жертва уничтожает логово культистов»."
  },
  AvgVideoCaption_124223_Content_127 = {
    Text = "Инспектор, я постараюсь вернуться домой"
  },
  AvgVideoCaption_124223_Content_128 = {
    Text = "Но если план провалится, не беспокойтесь, потому что в любом случае"
  },
  AvgVideoCaption_124223_Content_129 = {
    Text = "В моей жизни будет грандиозный финал"
  },
  AvgVideoCaption_124223_Content_13 = {
    Text = "Я только увидел, как некоторые люди в черных мантиях внезапно появились передо мной"
  },
  AvgVideoCaption_124223_Content_130 = {
    Text = "Стон этих сектантов станет лучшими аплодисментами"
  },
  AvgVideoCaption_124223_Content_14 = {
    Text = "Преследуя людей, которых они называют жертвами, с серебряным кинжалом в руках"
  },
  AvgVideoCaption_124223_Content_15 = {
    Text = "А те люди, кричали, всхлипывали, шумели так, что у меня голова готова взорваться"
  },
  AvgVideoCaption_124223_Content_16 = {
    Text = "Шумно до смерти, заткнись!"
  },
  AvgVideoCaption_124223_Content_17 = {
    Text = "Никто не обращает на меня внимания"
  },
  AvgVideoCaption_124223_Content_18 = {
    Text = "Если не считать тот Кинжал, вонзенный в моё плечо"
  },
  AvgVideoCaption_124223_Content_19 = {
    Text = "Похоже, вы предпочитаете здороваться с помощью оружия?"
  },
  AvgVideoCaption_124223_Content_2 = {
    Text = "Ведение дневника помогает упорядочить память и сохранять рассудок"
  },
  AvgVideoCaption_124223_Content_20 = {
    Text = "Как здорово, я тоже"
  },
  AvgVideoCaption_124223_Content_21 = {
    Text = "Поприветствуй мою любимую топорик —"
  },
  AvgVideoCaption_124223_Content_22 = {
    Text = "Сияющий☆Мальстрём!"
  },
  AvgVideoCaption_124223_Content_23 = {
    Text = "Один за другим... В тумане, о котором никто не знает, я с удовольствием выплескиваю свои эмоции♪"
  },
  AvgVideoCaption_124223_Content_24 = {
    Text = "Постучите по своей голове, углубитесь в свой мозг, давайте проведем время в погоне♪"
  },
  AvgVideoCaption_124223_Content_25 = {
    Text = "Наконец, мир стал чистым"
  },
  AvgVideoCaption_124223_Content_26 = {
    Text = "Я жду, когда детектив придёт убирать за собой"
  },
  AvgVideoCaption_124223_Content_27 = {
    Text = "Не знаю, сколько слов нужно будет написать в отчёте о «поспешных действиях» на этот раз"
  },
  AvgVideoCaption_124223_Content_28 = {
    Text = "Но на следующий, третий и четвертый день никто не пришел ко мне"
  },
  AvgVideoCaption_124223_Content_29 = {
    Text = "Только неизвестные монстры из густого тумана продолжают доставлять мне неприятности"
  },
  AvgVideoCaption_124223_Content_3 = {
    Text = "Ха, разум?"
  },
  AvgVideoCaption_124223_Content_30 = {
    Text = "Черт возьми, эти парни не могут оставить мне время поесть?"
  },
  AvgVideoCaption_124223_Content_31 = {
    Text = "Я тоже хочу спать, хорошо!"
  },
  AvgVideoCaption_124223_Content_32 = {
    Text = "И это туманное бедствие, сколько же времени нам ещё нужно, чтобы выбраться отсюда!"
  },
  AvgVideoCaption_124223_Content_33 = {
    Text = "Последователь, твоя Моша умрёт от голода и жажды"
  },
  AvgVideoCaption_124223_Content_34 = {
    Text = "Умру от усталости в этой катастрофе тумана, полной только чудовищ тумана"
  },
  AvgVideoCaption_124223_Content_35 = {
    Text = "Где же ты на самом деле?!"
  },
  AvgVideoCaption_124223_Content_36 = {
    Text = "Очень голоден, очень хочу пить, очень устал..."
  },
  AvgVideoCaption_124223_Content_37 = {
    Text = "Так умирать слишком легко"
  },
  AvgVideoCaption_124223_Content_38 = {
    Text = "Я думал, что моя жизнь закончится эффектно..."
  },
  AvgVideoCaption_124223_Content_39 = {
    Text = "Самое важное"
  },
  AvgVideoCaption_124223_Content_4 = {
    Text = "С тех пор как я inexplicably переместился в этот мир, я уже не могу сохранять рассудок"
  },
  AvgVideoCaption_124223_Content_40 = {
    Text = "Я не хочу... быть одному..."
  },
  AvgVideoCaption_124223_Content_41 = {
    Text = "Ну, на каком дне я остановился?"
  },
  AvgVideoCaption_124223_Content_42 = {
    Text = "О, пятый день"
  },
  AvgVideoCaption_124223_Content_43 = {
    Text = "Я, Моша, все еще существую в этом скучном мире"
  },
  AvgVideoCaption_124223_Content_44 = {
    Text = "«Местные выжившие» в туманном бедствии спасли меня"
  },
  AvgVideoCaption_124223_Content_45 = {
    Text = "После бессмысленного разговора"
  },
  AvgVideoCaption_124223_Content_46 = {
    Text = "Я наконец понял, что я «пересекся»"
  },
  AvgVideoCaption_124223_Content_47 = {
    Text = "С тех пор нет горячего чая из лесного ореха, нет ароматной тушеной рыбы с ривенрогом"
  },
  AvgVideoCaption_124223_Content_48 = {
    Text = "Только твёрдый чёрный хлеб и мутная вода с песком"
  },
  AvgVideoCaption_124223_Content_49 = {
    Text = "Но я тоже не могу ни на что жаловаться"
  },
  AvgVideoCaption_124223_Content_5 = {
    Text = "Но, раз пока не удаётся вернуться, надо найти что-то развлекательное, чтобы скоротать время..."
  },
  AvgVideoCaption_124223_Content_50 = {
    Text = "В конце концов, этот городок потерял связь с внешним миром"
  },
  AvgVideoCaption_124223_Content_51 = {
    Text = "Туманное бедствие снова заперло всех, каждый из них иссох и выглядит измождённым"
  },
  AvgVideoCaption_124223_Content_52 = {
    Text = "Дух постепенно разрушается в ежедневных муках"
  },
  AvgVideoCaption_124223_Content_53 = {
    Text = "Я считаю, что жизнь сейчас довольно интересна, за исключением «потери свободы»"
  },
  AvgVideoCaption_124223_Content_54 = {
    Text = "Когда скучно, я выхожу убивать монстров"
  },
  AvgVideoCaption_124223_Content_55 = {
    Text = "Также можно будет забрать новые ресурсы, двойная выгода"
  },
  AvgVideoCaption_124223_Content_56 = {
    Text = "Скажем так, здесь как в парке аттракционов"
  },
  AvgVideoCaption_124223_Content_57 = {
