  AvgVideoCaption_124223_Content_59 = {
    Text = "Иногда можно увидеть, как другие дерутся до крови и ссадин, это действительно весело"
  },
  AvgVideoCaption_124223_Content_6 = {
    Text = "Не думал, что у меня тоже будут моменты, когда я буду писать такие скучные вещи, как дневник..."
