  AvgVideoCaption_124223_Content_86 = {
    Text = "Двадцать первый день, вяленое оленина, проросший картофель…"
  },
  AvgVideoCaption_124223_Content_87 = {
    Text = "Что я, черт возьми, делаю? Моша, ты что, забыла свою цель? Твоя цель - вернуться домой"
  },
  AvgVideoCaption_124223_Content_88 = {
    Text = "А не быть здесь наемником, собирая вяленое олениное Инкарнация и проросший картофель"
