  AvgVideoCaption_124223_Content_94 = {
    Text = "Аааааа——выдай мне это,Выплюнь их"
  },
  AvgVideoCaption_124223_Content_95 = {
    Text = "Ты думаешь, что я не смогу тебя убить? Нет, я не боюсь ничего, я могу победить всё"
