  AvgVideoCaption_126905_Content_101 = {
    Text = "Малышка, ты поняла ту историю"
  },
  AvgVideoCaption_126905_Content_102 = {
    Text = "У нас осталась последняя вещь, которую нужно сделать"
  },
  AvgVideoCaption_126905_Content_103 = {
    Text = "Папа хочет остановить нас быть вместе"
