  AvgVideoCaption_126905_Content_110 = {
    Text = "Совершенно, совершенно, иди ко мне\nСовершенно, совершенно, иди к маме"
  },
  AvgVideoCaption_126905_Content_111 = {
    Text = "А затем я позабочусь о том, чтобы этот сладкий Подарок навсегда принадлежал тебе"
