  AvgVideoCaption_126905_Content_14 = {
    Text = "Что же сделает Матушка человечества в это время..."
  },
  AvgVideoCaption_126905_Content_15 = {
    Text = "Позволь мне рассказать тебе одну сказку на ночь"
