  AvgVideoCaption_126905_Content_5 = {
    Text = "Я поймаю облако, чтобы ты мог на нем удобно устроиться..."
  },
  AvgVideoCaption_126905_Content_50 = {
    Text = "«Ма Мингминь абсолютно идентична этому.»"
  },
  AvgVideoCaption_126905_Content_51 = {
    Text = "«Какой прекрасный скакун, поздравляю ваше величество с этой замечательной лошадью.»"
  },
  AvgVideoCaption_126905_Content_52 = {
    Text = "Возможно, это Страх перед властью властителей, возможно, слишком громкие голоса подхалимов"
  },
  AvgVideoCaption_126905_Content_53 = {
    Text = "Немногие сказали, что это звук оленя, но он быстро был затоплен волной звуков"
