  AvgVideoCaption_126905_Content_59 = {
    Text = "Нелепо издавая странный свист"
  },
  AvgVideoCaption_126905_Content_6 = {
    Text = "Да, в Край без снов, это не что-то необычное"
  },
  AvgVideoCaption_126905_Content_60 = {
    Text = "Властный Министр спокойно поглаживал его"
