  AvgVideoCaption_126905_Content_63 = {
    Text = "С тех пор"
  },
  AvgVideoCaption_126905_Content_64 = {
    Text = "Странная Чёрная Чёрная тень, превращённая из оленя в лошадь, всё время следовала за королём"
  },
  AvgVideoCaption_126905_Content_65 = {
    Text = "Никто больше не обращает внимания на его величие"
