  AvgVideoCaption_126905_Content_67 = {
    Text = "Никто не обращал внимания на его всхлипы, вырывающиеся из горла, когда его мучил монстр"
  },
  AvgVideoCaption_126905_Content_68 = {
    Text = "Потому что независимо от того, происходит ли это из желания, страха, взвешивания или чего-то другого"
  },
  AvgVideoCaption_126905_Content_69 = {
    Text = "Люди встали на сторону властного министра"
