  },
  AvgVideoCaption_131662_Content_115 = {Text = "Но.."},
  AvgVideoCaption_131662_Content_116 = {
    Text = "Моск, давай! Спасай людей"
  },
  AvgVideoCaption_131662_Content_117 = {
