  AvgVideoCaption_131662_Content_118 = {
    Text = "O-1841Пробуждённый"
  },
  AvgVideoCaption_131662_Content_119 = {
    Text = "Слышите мой голос?"
  },
  AvgVideoCaption_131662_Content_12 = {
    Text = "Колледж Мисаг начинает пытаться установить контакт с системой пробуждения"
  },
  AvgVideoCaption_131662_Content_120 = {
    Text = "Хотя невозможно ощутить"
  },
  AvgVideoCaption_131662_Content_121 = {
    Text = "Но после исследования с помощью прибора @4 было обнаружено, что твоя Огромная Огромная сила будет искажать все вещи вокруг в бессознательном состоянии"
  },
  AvgVideoCaption_131662_Content_122 = {
    Text = "Спасибо, что попытались напомнить нам"
  },
  AvgVideoCaption_131662_Content_123 = {
    Text = "Если ты готов сотрудничать"
