  AvgVideoCaption_131662_Content_124 = {
    Text = "Мисаг может вам помочь"
  },
  AvgVideoCaption_131662_Content_125 = {
    Text = "Путем постоянного совершенствования ограничительных устройств"
  },
  AvgVideoCaption_131662_Content_126 = {
    Text = "Вы можете перенести и освободить силу вихря в пределах ограниченной области"
  },
  AvgVideoCaption_131662_Content_127 = {
    Text = "Нейтрализация"
  },
  AvgVideoCaption_131662_Content_128 = {
    Text = "Мальстрём... перемещение?"
  },
  AvgVideoCaption_131662_Content_129 = {
    Text = "Но перемещение координат может быть только вокруг тебя"
  },
  AvgVideoCaption_131662_Content_13 = {
    Text = "Ах, ах... ах———"
  },
  AvgVideoCaption_131662_Content_130 = {
    Text = "Поэтому вы должны всегда внимательно контролировать устройство сдерживания"
  },
  AvgVideoCaption_131662_Content_131 = {
    Text = "Мальстрём, перемещение"
  },
  AvgVideoCaption_131662_Content_132 = {
    Text = "Не можем, Урон..."
  },
  AvgVideoCaption_131662_Content_133 = {
    Text = "Нельзя, Урон, Близкий Близкий друг... Уголёк"
  },
  AvgVideoCaption_131662_Content_134 = {
    Text = "Мальстрём"
  },
  AvgVideoCaption_131662_Content_135 = {
    Text = "Перемещение"
  },
  AvgVideoCaption_131662_Content_136 = {Text = "Себя"},
  AvgVideoCaption_131662_Content_137 = {
    Text = "Подождите"
  },
  AvgVideoCaption_131662_Content_138 = {
    Text = "O-1841 пробуждающее тело, ты……"
