  AvgVideoCaption_131662_Content_140 = {
    Text = "Нет, Урон..."
  },
  AvgVideoCaption_131662_Content_141 = {
    Text = "Все волны исчезли..."
  },
  AvgVideoCaption_131662_Content_142 = {
    Text = "Ты перенес силу вихря в свое тело?"
  },
  AvgVideoCaption_131662_Content_143 = {Text = "Но"},
  AvgVideoCaption_131662_Content_144 = {
    Text = "В таком случае ты будешь испытывать нечеловеческую боль..."
  },
  AvgVideoCaption_131662_Content_145 = {Text = "Моск"},
  AvgVideoCaption_131662_Content_146 = {
    Text = "Не бойся"
  },
  AvgVideoCaption_131662_Content_147 = {
    Text = "Уголёк, обнять"
  },
  AvgVideoCaption_131662_Content_148 = {
    Text = "Уголёк, обнять, радостно"
  },
  AvgVideoCaption_131662_Content_149 = {
    Text = "Моск, радость"
  },
  AvgVideoCaption_131662_Content_15 = {
    Text = "Я не причиню тебе вреда"
  },
  AvgVideoCaption_131662_Content_16 = {
    Text = "Ты понимаешь, что я говорю, верно?"
  },
  AvgVideoCaption_131662_Content_17 = {
    Text = "Не переживайте, здесь очень безопасно"
  },
  AvgVideoCaption_131662_Content_18 = {
    Text = "Мы из Академии Мисаг, я исследователь системы пробуждения Эйлин Коуэлл"
  },
  AvgVideoCaption_131662_Content_19 = {
    Text = "Что ты встретил в том вихре?"
  },
  AvgVideoCaption_131662_Content_2 = {
    Text = "Звук, звук, так тихо..."
  },
  AvgVideoCaption_131662_Content_20 = {
    Text = "Нам очень нужна ваша информация, чтобы восстановить ситуацию по делу"
  },
  AvgVideoCaption_131662_Content_21 = {
    Text = "Теперь, пожалуйста, говорите в этот микрофон с сердечником из серебра"
  },
  AvgVideoCaption_131662_Content_22 = {
    Text = "Позже мы попытаемся вызвать технологии @1 для парсинга содержимого записи"
  },
  AvgVideoCaption_131662_Content_23 = {
    Text = "Что там произошло..."
  },
  AvgVideoCaption_131662_Content_24 = {
    Text = "Корабль"
  },
  AvgVideoCaption_131662_Content_25 = {
