  AvgVideoCaption_131662_Content_86 = {
    Text = "Пожалуйста, сохраняйте спокойствие, Моск"
  },
  AvgVideoCaption_131662_Content_87 = {
    Text = "Ты сейчас находишься в исследовательском центре пробуждающих тел Мисаг"
