  },
  AvgVideoCaption_131662_Content_9 = {
    Text = "Только в редкие моменты использует @2, разговаривает сам с собой и впадает в тяжелое состояние бреда"
  },
  AvgVideoCaption_131662_Content_90 = {
    Text = "Но среди них все еще есть много трудных для понимания слов"
  },
  AvgVideoCaption_131662_Content_91 = {
    Text = "Таким образом, нам нужно..."
  },
  AvgVideoCaption_131662_Content_92 = {
    Text = "Нет... нет, лицо, лицо"
