  AvgVideoCaption_131662_Content_99 = {
    Text = "Искажение... Мальстрём..."
  },
  AvgVideoCaption_134291_Content_1 = {
    Text = "Колесо Судьбы"
  },
  AvgVideoCaption_134291_Content_10 = {
    Text = "Всё это сплетено моими руками"
  },
  AvgVideoCaption_134291_Content_11 = {
    Text = "Всё это..."
  },
  AvgVideoCaption_134291_Content_12 = {
    Text = "Хе-хе-хе-хе..."
  },
  AvgVideoCaption_134291_Content_13 = {
    Text = "Никто не в силах противиться судьбе, дорогая сестра"
  },
  AvgVideoCaption_134291_Content_14 = {
    Text = "Мы неизбежно рассыплемся в очередную нить"
  },
  AvgVideoCaption_134291_Content_15 = {
    Text = "Все пути уже предрешены"
