  AvgVideoCaption_134291_Content_16 = {Text = "Судья"},
  AvgVideoCaption_134291_Content_17 = {
    Text = "Спаситель"
  },
  AvgVideoCaption_134291_Content_18 = {
    Text = "Носитель"
  },
  AvgVideoCaption_134291_Content_19 = {
    Text = "Узник..."
  },
  AvgVideoCaption_134291_Content_2 = {
    Text = "Ничтожное и хрупкое божество"
  },
  AvgVideoCaption_134291_Content_20 = {
    Text = "Роль, что мне уготована"
  },
  AvgVideoCaption_134291_Content_21 = {
    Text = "Давно лишена выбора"
  },
  AvgVideoCaption_134291_Content_22 = {
    Text = "Но и тебе не дано выбирать..."
