  },
  AvgVideoCaption_134291_Content_6 = {
    Text = "Поэзия"
  },
  AvgVideoCaption_134291_Content_7 = {Text = "Танцы"},
  AvgVideoCaption_134291_Content_8 = {
    Text = "Войны..."
  },
  AvgVideoCaption_134291_Content_9 = {
    Text = "Повседневность"
  },
  AvgVideoCaption_134292_Content_1 = {
    Text = "Подойди ко мне, Нефрея."
  },
  AvgVideoCaption_134292_Content_10 = {
    Text = "Как жаль эту героиню на сцене…"
