  },
  AvgVideoCaption_134292_Content_103 = {
    Text = "лишь бы не дать миру погрузиться во тьму…"
  },
  AvgVideoCaption_134292_Content_104 = {
    Text = "Иногда я думаю…"
  },
  AvgVideoCaption_134292_Content_105 = {
    Text = "Тебе не кажется, что я слишком упряма?"
  },
  AvgVideoCaption_134292_Content_106 = {
    Text = "Я понимаю тебя, сестра…"
  },
  AvgVideoCaption_134292_Content_107 = {
    Text = "Просто я не хочу, чтобы тебе было так тяжело."
  },
  AvgVideoCaption_134292_Content_108 = {
    Text = "Всё это не должно лежать на твоих плечах одной…"
  },
  AvgVideoCaption_134292_Content_109 = {
    Text = "Сестра,"
  },
  AvgVideoCaption_134292_Content_11 = {
    Text = "Её бросил тот, кого она любила?"
  },
  AvgVideoCaption_134292_Content_110 = {
    Text = "ты привела меня сегодня на эту оперу,"
  },
  AvgVideoCaption_134292_Content_111 = {
    Text = "чтобы рассказать мне обо всём этом?"
  },
  AvgVideoCaption_134292_Content_112 = {
    Text = "Судьба — это моя длинная тюрьма, Нефрея."
  },
  AvgVideoCaption_134292_Content_113 = {
    Text = "Я лишь надеюсь, что в конце ты увидишь моё одиночество,"
  },
  AvgVideoCaption_134292_Content_114 = {
    Text = "как единственный человек, которому я доверяю."
  },
  AvgVideoCaption_134292_Content_115 = {
    Text = "Доверяешь?"
  },
  AvgVideoCaption_134292_Content_116 = {
    Text = "Но… кажется, я всё время путаю твои нити."
  },
  AvgVideoCaption_134292_Content_117 = {
    Text = "Я не нарочно…"
  },
  AvgVideoCaption_134292_Content_118 = {
    Text = "Но каждый раз, когда я приближаюсь к тебе, я влияю на тебя…"
  },
  AvgVideoCaption_134292_Content_119 = {
    Text = "Все эти ровные, сияющие нити"
  },
  AvgVideoCaption_134292_Content_12 = {
    Text = "Страдания людей"
  },
  AvgVideoCaption_134292_Content_120 = {
    Text = "приходят в беспорядок из-за моего появления…"
  },
  AvgVideoCaption_134292_Content_121 = {
    Text = "Прости, сестра,"
  },
  AvgVideoCaption_134292_Content_122 = {
    Text = "я и сама не знаю, почему…"
  },
  AvgVideoCaption_134292_Content_123 = {
    Text = "Потому что ты прекрасна, Нефрея."
  },
  AvgVideoCaption_134292_Content_124 = {
    Text = "А эта клетка судьбы завидует всему прекрасному."
  },
  AvgVideoCaption_134292_Content_125 = {
    Text = "Красота — не твоя вина,"
  },
  AvgVideoCaption_134292_Content_126 = {
    Text = "дорогая сестрёнка."
  },
  AvgVideoCaption_134292_Content_127 = {
    Text = "Моя любовь и забота о тебе никогда не угасали из-за разногласий."
  },
  AvgVideoCaption_134292_Content_128 = {
    Text = "Я глубоко люблю каждую жизнь, на которую обращаю свой взор,"
  },
  AvgVideoCaption_134292_Content_129 = {
    Text = "Так же, как я всем сердцем люблю тебя — единственную, кто способен меня понять…"
  },
  AvgVideoCaption_134292_Content_13 = {
    Text = "вызваны не только любовью и предательством."
  },
  AvgVideoCaption_134292_Content_130 = {
    Text = "Спасибо тебе, сестра…"
  },
  AvgVideoCaption_134292_Content_131 = {
    Text = "…Усни в объятиях смерти, сестрёнка."
  },
  AvgVideoCaption_134292_Content_132 = {
    Text = "Сес… сестра?"
  },
  AvgVideoCaption_134292_Content_133 = {
    Text = "По… чему?"
  },
  AvgVideoCaption_134292_Content_134 = {
    Text = "Извини, Нефрея......"
  },
  AvgVideoCaption_134292_Content_135 = {
    Text = "Ради сохранения паутины судьбы"
  },
  AvgVideoCaption_134292_Content_136 = {
    Text = "я должна отсечь ошибочные пути."
  },
  AvgVideoCaption_134292_Content_137 = {
    Text = "Мучительная цена… И потому…"
  },
  AvgVideoCaption_134292_Content_138 = {
    Text = "Я и есть та цена, которую ты должна заплатить, верно?"
  },
  AvgVideoCaption_134292_Content_139 = {
    Text = "Хе… хе-хе-хе…"
  },
  AvgVideoCaption_134292_Content_14 = {
    Text = "Дорогая Нефрея."
  },
  AvgVideoCaption_134292_Content_140 = {
    Text = "Выбирать то, что ведёт к величию,"
  },
  AvgVideoCaption_134292_Content_141 = {
    Text = "отбрасывать всё ничтожное и грязное —"
  },
  AvgVideoCaption_134292_Content_142 = {
    Text = "вот что ты… вот твой вечный выбор…"
  },
  AvgVideoCaption_134292_Content_143 = {
    Text = "Лицемерие, предательство…"
  },
  AvgVideoCaption_134292_Content_144 = {
    Text = "Ты предала меня…"
  },
  AvgVideoCaption_134292_Content_145 = {
    Text = "Ты предала саму себя, сестра…"
  },
  AvgVideoCaption_134292_Content_146 = {
    Text = "Отвергни меня,"
  },
  AvgVideoCaption_134292_Content_147 = {
    Text = "покинь меня."
  },
  AvgVideoCaption_134292_Content_148 = {
    Text = "Уходи туда, где не нужно страдать ради верности,"
  },
  AvgVideoCaption_134292_Content_149 = {
    Text = "Нефрея......"
  },
  AvgVideoCaption_134292_Content_15 = {Text = "Она.."},
  AvgVideoCaption_134292_Content_150 = {
    Text = "Всё это — Колесо Судьбы, от которой мне не уйти."
  },
  AvgVideoCaption_134292_Content_151 = {
    Text = "Лицемерие, предательство…"
  },
  AvgVideoCaption_134292_Content_152 = {
    Text = "Ты предала меня…"
  },
  AvgVideoCaption_134292_Content_153 = {
    Text = "Ты предала саму себя!"
  },
  AvgVideoCaption_134292_Content_154 = {
    Text = "Однажды ты уничтожишь всё, что тебе дорого…"
  },
  AvgVideoCaption_134292_Content_155 = {
    Text = "Вместе с этой самообманчивой судьбой… Сестра…"
  },
  AvgVideoCaption_134292_Content_156 = {
    Text = "Ненавидь меня, Нефрея."
  },
  AvgVideoCaption_134292_Content_157 = {
    Text = "Но за всякую милость"
  },
  AvgVideoCaption_134292_Content_158 = {
    Text = "придётся заплатить жестокой судьбой."
  },
  AvgVideoCaption_134292_Content_159 = {
    Text = "Колесо судьбы безжалостно, оно вращается вновь и вновь."
  },
  AvgVideoCaption_134292_Content_16 = {
    Text = "Она оплакивает своё бессилие перед лицом судьбы."
  },
  AvgVideoCaption_134292_Content_160 = {
    Text = "Мне приходится отрекаться от тебя —"
  },
  AvgVideoCaption_134292_Content_161 = {
    Text = "раз за разом. Но пока я помню, ради чего плету нити судьбы…"
  },
  AvgVideoCaption_134292_Content_162 = {
    Text = "Даже если мне не суждено обрести твоё понимание,"
  },
  AvgVideoCaption_134292_Content_163 = {
    Text = "даже если придётся пожертвовать всем,"
  },
  AvgVideoCaption_134292_Content_164 = {
    Text = "я буду поступать именно так."
  },
  AvgVideoCaption_134292_Content_165 = {
    Text = "Такова моя ответственность как Ткача."
  },
  AvgVideoCaption_134292_Content_166 = {
    Text = "Таково одиночество, через которое я должна пройти."
  },
  AvgVideoCaption_134292_Content_167 = {
    Text = "Пусть же Колесо Судьбы…"
  },
  AvgVideoCaption_134292_Content_168 = {
    Text = "навеки свяжет нас с тобой."
  },
  AvgVideoCaption_134292_Content_17 = {
    Text = "Эта героиня совсем не умна."
  },
  AvgVideoCaption_134292_Content_18 = {
    Text = "Ей нужно лишь помолиться кому-то вроде тебя, сестрица, — тому, кто способен изменить судьбу."
  },
  AvgVideoCaption_134292_Content_19 = {
    Text = "Правда?"
  },
  AvgVideoCaption_134292_Content_2 = {
    Text = "Сестрица, ты ведь впервые привела меня в свой театр!"
  },
  AvgVideoCaption_134292_Content_20 = {
    Text = "Судьба наделила меня властью плести её нити,"
  },
  AvgVideoCaption_134292_Content_21 = {
    Text = "но я не в силах даровать покой каждому…"
  },
  AvgVideoCaption_134292_Content_22 = {
    Text = "В этом мире и впрямь существуют счастливые судьбы,"
  },
  AvgVideoCaption_134292_Content_23 = {
    Text = "но кто-то должен принять на себя безумие и Разрушение, что должны были обрушиться на них."
  },
  AvgVideoCaption_134292_Content_24 = {
    Text = "Я храню эту паутину судеб,"
  },
  AvgVideoCaption_134292_Content_25 = {
    Text = "нитями сплетая радости и горести бесчисленных людей."
  },
  AvgVideoCaption_134292_Content_26 = {
    Text = "Но в конце концов…"
  },
  AvgVideoCaption_134292_Content_27 = {
    Text = "я лишь неуклюжая актриса в собственном сценарии."
  },
  AvgVideoCaption_134292_Content_28 = {
    Text = "Как же так,"
  },
  AvgVideoCaption_134292_Content_29 = {
    Text = "ведь ты, сестрица, способна повелевать судьбой!"
  },
  AvgVideoCaption_134292_Content_3 = {
    Text = "Что мы будем смотреть? Драму? Балет?"
  },
  AvgVideoCaption_134292_Content_30 = {
    Text = "На концах нитей — лишь хаотическая пустота."
  },
  AvgVideoCaption_134292_Content_31 = {
    Text = "Повелительница судьбы"
  },
  AvgVideoCaption_134292_Content_32 = {
    Text = "в конечном счёте — лишь её рабыня…"
  },
  AvgVideoCaption_134292_Content_33 = {
    Text = "Нефрея"
  },
  AvgVideoCaption_134292_Content_34 = {
    Text = "Моя единственная сестрёнка."
  },
  AvgVideoCaption_134292_Content_35 = {
    Text = "Быть может…"
  },
  AvgVideoCaption_134292_Content_36 = {
    Text = "лишь ты способна по-настоящему понять это одиночество."
  },
  AvgVideoCaption_134292_Content_37 = {
    Text = "Оказывается… сестрица тоже не всемогуща…"
  },
  AvgVideoCaption_134292_Content_38 = {
    Text = "Я не совсем понимаю…"
  },
  AvgVideoCaption_134292_Content_39 = {
    Text = "Но что бы ни случилось,"
  },
  AvgVideoCaption_134292_Content_4 = {
    Text = "Ну скажи скорее!"
  },
  AvgVideoCaption_134292_Content_40 = {
    Text = "я всегда буду рядом с тобой, сестрица!"
  },
  AvgVideoCaption_134292_Content_41 = {
    Text = "Кажется, я кое-что поняла,"
  },
  AvgVideoCaption_134292_Content_42 = {
    Text = "Сестра.."
  },
  AvgVideoCaption_134292_Content_43 = {
    Text = "эта певица,"
  },
  AvgVideoCaption_134292_Content_44 = {
    Text = "Увядший лист, бессильно носимый ветром,"
  },
  AvgVideoCaption_134292_Content_45 = {
    Text = "лишь покорно принимающий удары судьбы…"
  },
  AvgVideoCaption_134292_Content_46 = {
    Text = "Какая жалкая участь…"
  },
  AvgVideoCaption_134292_Content_47 = {
    Text = "Нефрея"
  },
  AvgVideoCaption_134292_Content_48 = {
    Text = "Если бы ты писала её историю,"
  },
  AvgVideoCaption_134292_Content_49 = {
    Text = "какую судьбу ты бы ей уготовила?"
  },
  AvgVideoCaption_134292_Content_5 = {
    Text = "Тише, представление начинается."
  },
  AvgVideoCaption_134292_Content_50 = {
    Text = "Хм, думаю, я бы написала для неё самую грандиозную трагедию!"
  },
  AvgVideoCaption_134292_Content_51 = {
    Text = "Отвергнутая всеми,"
  },
  AvgVideoCaption_134292_Content_52 = {
    Text = "обречённая быть лишь второстепенным персонажем…"
  },
  AvgVideoCaption_134292_Content_53 = {
    Text = "Если бы я переписывала её судьбу, я бы разожгла пламя,"
  },
  AvgVideoCaption_134292_Content_54 = {
    Text = "чтобы всё, что терзало её, сковывало её,"
  },
  AvgVideoCaption_134292_Content_55 = {
    Text = "всю несправедливость — обратить в Пепел!"
  },
  AvgVideoCaption_134292_Content_56 = {
    Text = "Скорбно, неистово, в грохоте и крушении…"
  },
  AvgVideoCaption_134292_Content_57 = {
    Text = "Та красота, что сжигает всё дотла, —"
  },
  AvgVideoCaption_134292_Content_58 = {
    Text = "вот что подходит ей больше всего!"
  },
  AvgVideoCaption_134292_Content_59 = {
    Text = "Да, Нефрея."
  },
  AvgVideoCaption_134292_Content_6 = {
    Text = "Сегодня вечером… это опера."
  },
  AvgVideoCaption_134292_Content_60 = {
    Text = "Ты по-прежнему считаешь,"
  },
  AvgVideoCaption_134292_Content_61 = {
    Text = "что Колесо Судьбы должна завершаться разрушением."
  },
  AvgVideoCaption_134292_Content_62 = {
    Text = "Ради трагически прекрасного замысла,"
  },
  AvgVideoCaption_134292_Content_63 = {
    Text = "ради сохранения совершенства,"
  },
  AvgVideoCaption_134292_Content_64 = {
    Text = "ты без колебаний обрекаешь людей на горестный Конец…"
  },
  AvgVideoCaption_134292_Content_65 = {
    Text = "Ч-что? Конечно нет!"
  },
  AvgVideoCaption_134292_Content_66 = {
    Text = "Мне просто нравится горечь, что остаётся после угасшей страсти,"
  },
  AvgVideoCaption_134292_Content_67 = {
    Text = "так же, как тебе нравятся счастливые финалы!"
  },
  AvgVideoCaption_134292_Content_68 = {
    Text = "Но, сестра,"
  },
  AvgVideoCaption_134292_Content_69 = {
    Text = "если Колесо Судьбы обречена на гибель, почему бы просто не отпустить?"
  },
  AvgVideoCaption_134292_Content_7 = {
    Text = "Женщина, заточённая судьбой,"
  },
  AvgVideoCaption_134292_Content_70 = {
    Text = "Позволить им идти к неизбежной гибели — разве это не прекрасно?"
  },
  AvgVideoCaption_134292_Content_71 = {
    Text = "Колесо судьбы вращается безжалостно,"
  },
  AvgVideoCaption_134292_Content_72 = {
    Text = "даже тебе не под силу изменить финал."
  },
  AvgVideoCaption_134292_Content_73 = {
    Text = "Зачем хранить паутину судьбы, упорствуя в этом тщетном труде?"
  },
  AvgVideoCaption_134292_Content_74 = {
    Text = "Колесо судьбы и впрямь безжалостно."
  },
  AvgVideoCaption_134292_Content_75 = {
    Text = "Но смысл его вращения — не в том, чтобы уничтожить всё,"
  },
  AvgVideoCaption_134292_Content_76 = {
    Text = "а в том, чтобы жизнь продолжалась в установленном порядке."
  },
  AvgVideoCaption_134292_Content_77 = {
    Text = "Взгляни на ту героиню на сцене."
  },
  AvgVideoCaption_134292_Content_78 = {
    Text = "Судьба отвернулась от неё,"
  },
  AvgVideoCaption_134292_Content_79 = {
    Text = "она претерпела бесчисленные страдания,"
  },
  AvgVideoCaption_134292_Content_8 = {
    Text = "ожидает своего спасения."
  },
  AvgVideoCaption_134292_Content_80 = {
    Text = "она плакала от собственного бессилия и горькой участи..."
  },
  AvgVideoCaption_134292_Content_81 = {
    Text = "Даже не веря в счастливые концовки,"
  },
  AvgVideoCaption_134292_Content_82 = {
    Text = "она так и не сдалась."
  },
  AvgVideoCaption_134292_Content_83 = {
    Text = "Если бы она сдалась,"
  },
  AvgVideoCaption_134292_Content_84 = {
    Text = "вся эта Колесо Судьбы утратила бы всякий смысл."
  },
  AvgVideoCaption_134292_Content_85 = {
    Text = "Среди всеобщего запустения"
  },
  AvgVideoCaption_134292_Content_86 = {
    Text = "Всегда нужен кто-то, кто будет хранить надежду,"
  },
  AvgVideoCaption_134292_Content_87 = {
    Text = "дорогая сестрёнка."
  },
  AvgVideoCaption_134292_Content_88 = {
    Text = "Я понимаю, сестра…"
  },
  AvgVideoCaption_134292_Content_89 = {
    Text = "Та, кто рыдала на сцене, — это ты, верно?"
  },
  AvgVideoCaption_134292_Content_9 = {
    Text = "«Жестокая Колесо Судьбы»…"
  },
  AvgVideoCaption_134292_Content_90 = {
    Text = "Я видела, как людей перемалывают страдания,"
  },
  AvgVideoCaption_134292_Content_91 = {
    Text = "как в монотонном и безмолвном течении они движутся к концу, день за днём."
  },
  AvgVideoCaption_134292_Content_92 = {
    Text = "Эта бесконечная тьма, бескрайнее одиночество…"
  },
  AvgVideoCaption_134292_Content_93 = {
    Text = "Если воздать жизни таким будущим —"
  },
  AvgVideoCaption_134292_Content_94 = {
    Text = "это, без сомнения, предательство самой жизни."
  },
  AvgVideoCaption_134292_Content_95 = {
    Text = "Именно потому, что я дорожу каждым ударом сердца,"
  },
  AvgVideoCaption_134292_Content_96 = {
    Text = "каждой пролитой слезой…"
  },
  AvgVideoCaption_134292_Content_97 = {
    Text = "я не могу позволить миру соскользнуть в бездну небытия."
  },
  AvgVideoCaption_134292_Content_98 = {
    Text = "Это мой выбор,"
  },
  AvgVideoCaption_134292_Content_99 = {
    Text = "и мне предстоит заплатить за него свою цену."
  },
  AvgVideoCaption_139854_Content_1 = {
    Text = "Первое письмо"
  },
  AvgVideoCaption_139854_Content_10 = {
    Text = "Наверное, это и называется «Любовь»"
  },
  AvgVideoCaption_139854_Content_11 = {
    Text = "У любого времени есть момент Конца."
  },
  AvgVideoCaption_139854_Content_12 = {
    Text = "История не вечна."
  },
  AvgVideoCaption_139854_Content_13 = {
    Text = "Я, нынешняя, кажется, нахожусь здесь и сейчас."
  },
  AvgVideoCaption_139854_Content_14 = {
    Text = "Я снова и снова глубоко осознаю,"
  },
  AvgVideoCaption_139854_Content_15 = {
    Text = "Это вселенная без @3"
  },
  AvgVideoCaption_139854_Content_16 = {
    Text = "Третье письмо"
  },
  AvgVideoCaption_139854_Content_17 = {
    Text = "Воспоминания о «Себе» постепенно возвращаются."
  },
  AvgVideoCaption_139854_Content_18 = {
    Text = "Кажется, я стала лучше понимать происходящее здесь."
  },
  AvgVideoCaption_139854_Content_19 = {
    Text = "Цивилизация здесь, пожалуй, довольно отсталая."
  },
  AvgVideoCaption_139854_Content_2 = {
    Text = "В этот момент моё сознание находится здесь."
  },
  AvgVideoCaption_139854_Content_20 = {
    Text = "Впрочем, в этом тоже есть своя прелесть. Хотя мне это не особо мешает."
  },
  AvgVideoCaption_139854_Content_21 = {
    Text = "Думала, что технологии и всё такое будут более развитыми…"
  },
  AvgVideoCaption_139854_Content_22 = {
    Text = "Но помимо этого, всё время чувствую, что есть что-то более важное. Что же это такое?"
  },
  AvgVideoCaption_139854_Content_23 = {
    Text = "Очень важное дело. Очень дорогой человек."
  },
  AvgVideoCaption_139854_Content_24 = {
    Text = "Когда не понимаю — охватывает Тревога, но всё равно хочу узнать больше."
  },
  AvgVideoCaption_139854_Content_25 = {
    Text = "Хочу поскорее узнать. Хочу поскорее встретиться. Что же это такое?"
  },
  AvgVideoCaption_139854_Content_26 = {
    Text = "Уже от одной этой мысли становится очень радостно."
  },
  AvgVideoCaption_139854_Content_27 = {
    Text = "Было бы здорово, если бы ты смог меня найти…"
  },
  AvgVideoCaption_139854_Content_28 = {
    Text = "Четвёртое письмо"
  },
  AvgVideoCaption_139854_Content_29 = {
    Text = "Самые разные воспоминания нахлынули разом."
  },
  AvgVideoCaption_139854_Content_3 = {
    Text = "Здесь всё незнакомо и пусто."
  },
  AvgVideoCaption_139854_Content_30 = {
    Text = "Словно накрытая мощной Силой"
  },
  AvgVideoCaption_139854_Content_31 = {
    Text = "Очень холодно, словно тело вот-вот разорвёт на части — Разрыв"
  },
  AvgVideoCaption_139854_Content_32 = {
    Text = "Очень счастливо, словно всё тело охватывает жар"
  },
  AvgVideoCaption_139854_Content_33 = {
    Text = "Воспоминания Ужаса, радостные воспоминания, воспоминания восторга, воспоминания печали"
  },
  AvgVideoCaption_139854_Content_34 = {
    Text = "Но самое важное воспоминание — только одно."
  },
  AvgVideoCaption_139854_Content_35 = {
    Text = "Воспоминание, прожитое вместе с дорогим тобой."
  },
  AvgVideoCaption_139854_Content_36 = {
    Text = "Где же это воспоминание…"
  },
  AvgVideoCaption_139854_Content_37 = {
    Text = "Пятое письмо"
  },
  AvgVideoCaption_139854_Content_38 = {
    Text = "Место, такое же бескрайнее, как пустыня."
  },
  AvgVideoCaption_139854_Content_39 = {
    Text = "Вокруг ни единой травинки, ни единого дерева."
  },
  AvgVideoCaption_139854_Content_4 = {
    Text = "Ты тоже где-то на этой планете?"
  },
  AvgVideoCaption_139854_Content_40 = {
    Text = "Если семя одуванчика упадёт в такую пустыню…"
  },
  AvgVideoCaption_139854_Content_41 = {
    Text = "Унесённое ветром так далеко-далеко от родных мест,"
  },
  AvgVideoCaption_139854_Content_42 = {
    Text = "о чём же думает это маленькое семечко?"
  },
  AvgVideoCaption_139854_Content_43 = {
    Text = "Если бы в той пустыне — хотя бы один человек"
  },
  AvgVideoCaption_139854_Content_44 = {
    Text = "знал, что есть тот, кто любит цветы,"
  },
  AvgVideoCaption_139854_Content_45 = {
    Text = "говорил бы: «Как красив цветок одуванчика»,"
  },
  AvgVideoCaption_139854_Content_46 = {
    Text = "если бы он мог всегда быть рядом,"
  },
  AvgVideoCaption_139854_Content_47 = {
    Text = "навсегда, у моего бока,"
  },
  AvgVideoCaption_139854_Content_48 = {
    Text = "если бы ты был здесь…"
  },
  AvgVideoCaption_139854_Content_49 = {
    Text = "Благодарю вас.."
  },
  AvgVideoCaption_139854_Content_5 = {
    Text = "Второе письмо"
  },
  AvgVideoCaption_139854_Content_50 = {
    Text = "Не забуду…"
  },
  AvgVideoCaption_139854_Content_6 = {
    Text = "Я помню встречу с важным для меня человеком."
  },
  AvgVideoCaption_139854_Content_7 = {
    Text = "В том взгляде была лишь лёгкая удивлённость…"
  },
  AvgVideoCaption_139854_Content_8 = {
    Text = "Ни Страха, ни Алчности"
  },
  AvgVideoCaption_139854_Content_9 = {
    Text = "Всегда такой нежный ко мне"
  },
  AvgVideoCaption_139855_Content_1 = {
    Text = "Ты помнишь меня?"
  },
  AvgVideoCaption_139855_Content_2 = {
    Text = "Когда любовь прорастает Каро"
  },
  AvgVideoCaption_139855_Content_3 = {
    Text = "Это принадлежит нам"
  },
  AvgVideoCaption_139855_Content_4 = {
    Text = "Прекрасный"
  },
  AvgVideoCaption_139855_Content_5 = {
    Text = "И жестокий мир"
  },
  AvgVideoCaption_139855_Content_6 = {
    Text = "Хе-хе, хе-хе-хе-хе"
  },
  AvgVideoCaption_139855_Content_7 = {Text = "И ещё"},
  AvgVideoCaption_139855_Content_8 = {
    Text = "Именуемое встречей"
  },
  AvgVideoCaption_139855_Content_9 = {
    Text = "Маленькое чудо"
  },
  AvgVideoCaption_143591_Content_1 = {
    Text = "Незачем делать такую Эмоцию"
  },
  AvgVideoCaption_143591_Content_10 = {
    Text = "Возможно, ты действительно получил бы удовлетворение от меня, ещё охваченного Негодованием"
  },
  AvgVideoCaption_143591_Content_11 = {
    Text = "Поверь мне, я пробовал Мрак, боль, Разделение кровных уз"
  },
  AvgVideoCaption_143591_Content_12 = {
    Text = "Пробовал заставить кораллы расти вместе с вашими костями"
  },
  AvgVideoCaption_143591_Content_13 = {
    Text = "Позволить морской воде разъедать вашу кожу"
  },
  AvgVideoCaption_143591_Content_14 = {
    Text = "Морским желудям истачивать ваше Каро"
  },
  AvgVideoCaption_143591_Content_15 = {
    Text = "Я думал, что чем больше ваших страданий"
  },
  AvgVideoCaption_143591_Content_16 = {
    Text = "Тем меньше будет моих"
  },
  AvgVideoCaption_143591_Content_17 = {
    Text = "Однако это было не так"
  },
  AvgVideoCaption_143591_Content_18 = {
    Text = "Я совершил ошибку"
  },
  AvgVideoCaption_143591_Content_19 = {
    Text = "Мою ошибку"
  },
  AvgVideoCaption_143591_Content_2 = {
    Text = "Я знаю о ваших жалких и нелепых безумных идеях"
  },
  AvgVideoCaption_143591_Content_20 = {
    Text = "Породила сама ваша глупость и слепая вера, распространившие непостижимый Ужас и катастрофу"
  },
  AvgVideoCaption_143591_Content_21 = {
    Text = "Что привело всё к такому положению"
  },
  AvgVideoCaption_143591_Content_22 = {
    Text = "Я всё ещё считаю вас людьми"
  },
  AvgVideoCaption_143591_Content_23 = {
    Text = "Чем грязнее страдание"
  },
  AvgVideoCaption_143591_Content_24 = {
    Text = "Тем большей наградой оно станет для таких нечистых тварей, как вы"
  },
  AvgVideoCaption_143591_Content_25 = {
    Text = "Будь то физическая боль"
  },
  AvgVideoCaption_143591_Content_26 = {
    Text = "Или душевные муки"
  },
  AvgVideoCaption_143591_Content_27 = {
    Text = "Всё это заставляет вас верить, что ваше Жертвоприношение безмерно возвышенно"
  },
  AvgVideoCaption_143591_Content_28 = {
    Text = "Что после смерти ваш мерзкий и ничтожный бог уведёт вас в так называемый новый мир"
  },
  AvgVideoCaption_143591_Content_29 = {
    Text = "Поэтому..."
  },
  AvgVideoCaption_143591_Content_3 = {
    Text = "Я понимаю"
  },
  AvgVideoCaption_143591_Content_30 = {
    Text = "Ах, всё именно так, как ты и видишь"
  },
  AvgVideoCaption_143591_Content_31 = {
    Text = "Сервини, Тристан, Сирил, Нэш… каждый из них"
  },
  AvgVideoCaption_143591_Content_32 = {
    Text = "Те, кого ты считал погибшими вместе с тобой ради вашей возвышенной веры"
  },
  AvgVideoCaption_143591_Content_33 = {
    Text = "Они все здесь"
  },
  AvgVideoCaption_143591_Content_34 = {
    Text = "Сервини — более Преданная и безумная, чем ты, нашедшая достойную смерть"
  },
  AvgVideoCaption_143591_Content_35 = {
    Text = "Застенчивый, непреклонный Сирил, расплавивший собственные кишки…"
  },
  AvgVideoCaption_143591_Content_36 = {
    Text = "Вы ничего не знаете о Бездне"
  },
  AvgVideoCaption_143591_Content_37 = {
    Text = "Давай, дыши глубже"
  },
  AvgVideoCaption_143591_Content_38 = {
    Text = "Расслабление"
  },
  AvgVideoCaption_143591_Content_39 = {
    Text = "Добро пожаловать обратно"
  },
  AvgVideoCaption_143591_Content_4 = {
    Text = "Вы хотите боли"
  },
  AvgVideoCaption_143591_Content_40 = {
    Text = "Теперь ты понимаешь, добыча?"
  },
  AvgVideoCaption_143591_Content_41 = {
    Text = "Бездна… не несёт с собой яростной резни"
  },
  AvgVideoCaption_143591_Content_42 = {
    Text = "Нет той упоительной Крови и огня, что ты себе представлял"
  },
  AvgVideoCaption_143591_Content_43 = {
    Text = "Только миллиарды тонн морской воды"
  },
  AvgVideoCaption_143591_Content_44 = {
    Text = "древняя материя, пробудившаяся вместе с этой планетой"
  },
  AvgVideoCaption_143591_Content_45 = {
    Text = "будет вечно подавлять вас"
  },
  AvgVideoCaption_143591_Content_46 = {
    Text = "обволакивать вас"
  },
  AvgVideoCaption_143591_Content_47 = {
    Text = "в бескрайней лазурной тьме"
  },
  AvgVideoCaption_143591_Content_48 = {
    Text = "Кроме меня"
  },
  AvgVideoCaption_143591_Content_49 = {
    Text = "ни один бог не сможет спасти вас и унести куда-либо"
  },
  AvgVideoCaption_143591_Content_5 = {
    Text = "Наказания, которое вас возбуждает"
  },
  AvgVideoCaption_143591_Content_50 = {
    Text = "У вас больше не будет никакого способа сбежать"
  },
  AvgVideoCaption_143591_Content_51 = {
    Text = "даже бесчисленные смерти снова и снова"
  },
  AvgVideoCaption_143591_Content_52 = {
    Text = "будь то как Тристан"
  },
  AvgVideoCaption_143591_Content_53 = {
    Text = "разорвавший себе горло"
  },
  AvgVideoCaption_143591_Content_54 = {
    Text = "или как умник Нэш"
  },
  AvgVideoCaption_143591_Content_55 = {
    Text = "пытавшийся разжевать собственный язык"
  },
  AvgVideoCaption_143591_Content_56 = {
    Text = "пробуйте сколько угодно"
  },
  AvgVideoCaption_143591_Content_57 = {
    Text = "вам не сбежать"
  },
  AvgVideoCaption_143591_Content_58 = {
    Text = "вы будете лишь постепенно угасать"
  },
  AvgVideoCaption_143591_Content_59 = {
    Text = "и снова возрождаться"
  },
  AvgVideoCaption_143591_Content_6 = {
    Text = "И в конце концов своей ничтожной смертью"
  },
  AvgVideoCaption_143591_Content_60 = {
    Text = "когда мне это наскучит"
  },
  AvgVideoCaption_143591_Content_61 = {
    Text = "даже возможность чувствовать боль станет для вас роскошью"
  },
  AvgVideoCaption_143591_Content_62 = {
    Text = "В Эпоянс есть лишь один закон"
  },
  AvgVideoCaption_143591_Content_63 = {
    Text = "Ваш ничтожный спаситель не придёт, добыча"
  },
  AvgVideoCaption_143591_Content_64 = {
    Text = "Я — единственное божество"
  },
  AvgVideoCaption_143591_Content_65 = {
    Text = "Падите ниц и принесите себя в жертву Океану"
  },
  AvgVideoCaption_143591_Content_66 = {
    Text = "И страдайте вечно в бездне"
  },
  AvgVideoCaption_143591_Content_7 = {
    Text = "Завершить Ритуал Жертвоприношения самих себя во имя Преданности"
  },
  AvgVideoCaption_143591_Content_8 = {
    Text = "Как жаль"
  },
  AvgVideoCaption_143591_Content_9 = {
    Text = "Тебе следовало прийти раньше"
  },
  AvgVideoCaption_148014_Content_1 = {
    Text = "Кто-то читает молитву Звёздному киту"
  },
  AvgVideoCaption_148014_Content_10 = {
    Text = "Эту неистовую силу Его — я её ощущаю…"
  },
  AvgVideoCaption_148014_Content_100 = {
    Text = "Я буду хранить живых существ этого места"
  },
  AvgVideoCaption_148014_Content_101 = {
    Text = "Я принесу покой этому городу"
  },
  AvgVideoCaption_148014_Content_102 = {
    Text = "Я принесу сюда нежный шёпот Звёздного кита…"
  },
  AvgVideoCaption_148014_Content_103 = {
    Text = "Ты... ты..."
  },
  AvgVideoCaption_148014_Content_104 = {
    Text = "Только что…"
  },
  AvgVideoCaption_148014_Content_105 = {
    Text = "Та, что только что…"
  },
  AvgVideoCaption_148014_Content_106 = {
    Text = "Мать троих детей!"
  },
  AvgVideoCaption_148014_Content_107 = {
    Text = "Правда?"
  },
  AvgVideoCaption_148014_Content_108 = {
    Text = "Что ж, поздравим их —"
  },
  AvgVideoCaption_148014_Content_109 = {
    Text = "им не придётся столько страдать"
  },
  AvgVideoCaption_148014_Content_11 = {
    Text = "Верующие, исповедующие Его"
  },
  AvgVideoCaption_148014_Content_110 = {
    Text = "Ты… ты же обещал…"
  },
  AvgVideoCaption_148014_Content_111 = {
    Text = "Принести вам избавление, даровать этому месту спасение —"
  },
  AvgVideoCaption_148014_Content_112 = {
    Text = "разве не в этом состояло моё обещание?"
  },
  AvgVideoCaption_148014_Content_113 = {
    Text = "Подожди! Подожди!"
  },
  AvgVideoCaption_148014_Content_114 = {
    Text = "Мы можем вместе пройти отбор Звёздного кита!"
  },
  AvgVideoCaption_148014_Content_115 = {
    Text = "Я могу помочь тебе, я могу…"
  },
  AvgVideoCaption_148014_Content_116 = {
    Text = "Неплохое предложение"
  },
  AvgVideoCaption_148014_Content_117 = {
    Text = "Жаль, но я уже дал тебе обещание"
  },
  AvgVideoCaption_148014_Content_118 = {
    Text = "Я держу своё слово"
  },
  AvgVideoCaption_148014_Content_119 = {
    Text = "Эти головы — в качестве жертвоприношения"
  },
  AvgVideoCaption_148014_Content_12 = {
    Text = "Все подвергаются разрушительному воздействию этой силы"
  },
  AvgVideoCaption_148014_Content_120 = {
    Text = "Должно хватить…"
  },
  AvgVideoCaption_148014_Content_121 = {
    Text = "Они не понимают, что такое сила"
  },
  AvgVideoCaption_148014_Content_122 = {
    Text = "И не понимают, чего ты хочешь"
  },
  AvgVideoCaption_148014_Content_123 = {
    Text = "Но я знаю"
  },
  AvgVideoCaption_148014_Content_124 = {
    Text = "Доказательство силы — я уже принёс его тебе"
  },
  AvgVideoCaption_148014_Content_125 = {
    Text = "Я вижу твою радость, Звёздный кит…"
  },
  AvgVideoCaption_148014_Content_126 = {
    Text = "Вот как открываются врата в это состязание……"
  },
  AvgVideoCaption_148014_Content_127 = {
    Text = "Скоро ты меня увидишь"
  },
  AvgVideoCaption_148014_Content_128 = {
    Text = "Жди моего появления……Левиафан"
  },
  AvgVideoCaption_148014_Content_13 = {
    Text = "Война, грабёж, убийство, кровь…"
  },
  AvgVideoCaption_148014_Content_14 = {
    Text = "Жажда Звёздного кита не знает конца"
  },
  AvgVideoCaption_148014_Content_15 = {
    Text = "Ты… неужели хочешь отвергнуть милость Бога-Отца?"
  },
  AvgVideoCaption_148014_Content_16 = {
    Text = "Я? Хм. Нет"
  },
  AvgVideoCaption_148014_Content_17 = {
    Text = "Я наслаждаюсь ими, Жрец"
  },
  AvgVideoCaption_148014_Content_18 = {
    Text = "Именно ради этого я сюда и пришла"
  },
  AvgVideoCaption_148014_Content_19 = {
    Text = "К сожалению"
  },
  AvgVideoCaption_148014_Content_2 = {
    Text = "Церковь, где размещают заражённых, находится здесь?"
  },
  AvgVideoCaption_148014_Content_20 = {
    Text = "Не каждый верующий способен вынести Его пылкое благословение"
  },
  AvgVideoCaption_148014_Content_21 = {
    Text = "Ах, да, именно так"
  },
  AvgVideoCaption_148014_Content_22 = {
    Text = "Эти бедные и счастливые верующие"
  },
  AvgVideoCaption_148014_Content_23 = {
    Text = "ликуют от силы Бога-Отца"
  },
  AvgVideoCaption_148014_Content_24 = {
    Text = "и впадают в безумие от этого ликования…"
  },
  AvgVideoCaption_148014_Content_25 = {
    Text = "Вот почему нам нужны такие верующие, как ты"
  },
  AvgVideoCaption_148014_Content_26 = {
    Text = "чтобы утешить дух Бога-Отца"
  },
  AvgVideoCaption_148014_Content_27 = {
    Text = "и спасти этих несчастных верующих. Только ты…"
  },
  AvgVideoCaption_148014_Content_28 = {
    Text = "Дорогой верующий"
  },
  AvgVideoCaption_148014_Content_29 = {
    Text = "надеюсь, ты помнишь своё обещание"
  },
  AvgVideoCaption_148014_Content_3 = {
    Text = "Именно!"
  },
  AvgVideoCaption_148014_Content_30 = {
    Text = "Я обещал тебе спасти тех, кто не в силах вынести благосклонность божества"
  },
  AvgVideoCaption_148014_Content_31 = {
    Text = "и помочь тебе спасти этот город"
  },
  AvgVideoCaption_148014_Content_32 = {
    Text = "Я никогда не нарушаю слова"
  },
  AvgVideoCaption_148014_Content_33 = {
    Text = "Это честь для этого города, верующий"
  },
  AvgVideoCaption_148014_Content_34 = {
    Text = "Однако ты говорил, что здесь есть несколько пострадавших"
  },
  AvgVideoCaption_148014_Content_35 = {
    Text = "но сейчас передо мной стоит не менее трёхсот человек"
  },
  AvgVideoCaption_148014_Content_36 = {
    Text = "Это преданный город"
  },
  AvgVideoCaption_148014_Content_37 = {
    Text = "Бог-Отец услышал наш зов…"
  },
  AvgVideoCaption_148014_Content_38 = {
    Text = "Голос Звёздного кита избрал нас!"
  },
  AvgVideoCaption_148014_Content_39 = {
    Text = "Это наша честь!"
  },
  AvgVideoCaption_148014_Content_4 = {
    Text = "Добро пожаловать в самое преданное святилище Звёздного кита"
  },
  AvgVideoCaption_148014_Content_40 = {
    Text = "Похоже, сейчас у них всё неплохо"
  },
  AvgVideoCaption_148014_Content_41 = {
    Text = "Это лишь временно…"
  },
  AvgVideoCaption_148014_Content_42 = {
    Text = "Если так продолжится, мы все станем сосудами воли Звёздного кита"
  },
  AvgVideoCaption_148014_Content_43 = {
    Text = "Они будут нашёптывать Его шёпот"
  },
  AvgVideoCaption_148014_Content_44 = {
    Text = "На коже проступят Его узоры……"
  },
  AvgVideoCaption_148014_Content_45 = {
    Text = "В конце концов наша воля сольётся со Звёздным китом воедино"
  },
  AvgVideoCaption_148014_Content_46 = {
    Text = "Разве не этого вы хотели?"
  },
  AvgVideoCaption_148014_Content_47 = {
    Text = "Конечно!"
  },
  AvgVideoCaption_148014_Content_48 = {
    Text = "Мы, верующие, всегда готовы отдать всё ради Бога-Отца!"
  },
  AvgVideoCaption_148014_Content_49 = {
    Text = "Но... не сейчас……"
  },
  AvgVideoCaption_148014_Content_5 = {
    Text = "Но они не заражённые"
  },
  AvgVideoCaption_148014_Content_50 = {
    Text = "Мы хотим услышать ещё больше откровений Бога-Отца……"
  },
  AvgVideoCaption_148014_Content_51 = {
    Text = "С благословения Бога-Отца я приму участие в Его отборе"
  },
  AvgVideoCaption_148014_Content_52 = {
    Text = "И стану Его единственным и неповторимым Заместителем!"
  },
  AvgVideoCaption_148014_Content_53 = {
    Text = "Поэтому до того момента, необходимо...."
  },
  AvgVideoCaption_148014_Content_54 = {
    Text = "Необходимо, чтобы кто-то сделал этот шаг раньше нас……"
  },
  AvgVideoCaption_148014_Content_55 = {
    Text = "Идите же, мои фанатичные верующие"
  },
  AvgVideoCaption_148014_Content_56 = {
    Text = "Наденьте на эту даму оковы и приведите её к алтарю!"
  },
  AvgVideoCaption_148014_Content_57 = {
    Text = "Это не входило в наш договор"
  },
  AvgVideoCaption_148014_Content_58 = {
    Text = "Дорогая дама, вы обещали мне"
  },
  AvgVideoCaption_148014_Content_59 = {
    Text = "Что пойдёте на всё"
  },
  AvgVideoCaption_148014_Content_6 = {
    Text = "Госпожа верующая"
  },
  AvgVideoCaption_148014_Content_60 = {
    Text = "Чтобы спасти этот несчастный город и этих несчастных верующих"
  },
  AvgVideoCaption_148014_Content_61 = {
    Text = "Я вижу"
  },
  AvgVideoCaption_148014_Content_62 = {
    Text = "Силу, переполняющую вас изнутри"
  },
  AvgVideoCaption_148014_Content_63 = {
    Text = "Именно это и дорого Богу-Отцу!"
  },
  AvgVideoCaption_148014_Content_64 = {
    Text = "Ты станешь самой лакомой жертвой для Звёздного кита!"
  },
  AvgVideoCaption_148014_Content_65 = {
    Text = "Стоит лишь принести тебя в жертву Богу-Отцу…"
  },
  AvgVideoCaption_148014_Content_66 = {
    Text = "И я получу благословение Бога-Отца…"
  },
  AvgVideoCaption_148014_Content_67 = {
    Text = "И смогу принять участие в этом священном состязании!"
  },
  AvgVideoCaption_148014_Content_68 = {
    Text = "Принеси себя в жертву…"
  },
  AvgVideoCaption_148014_Content_69 = {
    Text = "Пожертвуй собой, отдай мне свою силу!"
  },
  AvgVideoCaption_148014_Content_7 = {
    Text = "Звёздный кит — наш великий Бог-Отец"
  },
  AvgVideoCaption_148014_Content_70 = {
    Text = "И ты спасёшь этих несчастных!"
  },
  AvgVideoCaption_148014_Content_71 = {
    Text = "Пожертвовал собой"
  },
  AvgVideoCaption_148014_Content_72 = {
    Text = "Звёздный кит обратит на меня Свой благосклонный взор!"
  },
  AvgVideoCaption_148014_Content_73 = {
    Text = "Руны, дарованные Звёздным китом"
  },
  AvgVideoCaption_148014_Content_74 = {
    Text = "Способны пробудить самую сокровенную силу в ваших телах"
  },
  AvgVideoCaption_148014_Content_75 = {
    Text = "И поглотить вас силой, которую вы не в состоянии контролировать"
  },
  AvgVideoCaption_148014_Content_76 = {
    Text = "Эта руническая последовательность очень длинная"
  },
  AvgVideoCaption_148014_Content_77 = {
    Text = "Хе-хе-хе-хе..."
  },
  AvgVideoCaption_148014_Content_78 = {
    Text = "Если бы ты обнаружил это чуть раньше"
  },
  AvgVideoCaption_148014_Content_79 = {
    Text = "Возможно, ещё мог бы нас остановить"
  },
  AvgVideoCaption_148014_Content_8 = {
    Text = "Перед каждым отбором"
  },
  AvgVideoCaption_148014_Content_80 = {
    Text = "Но теперь уже нет шансов"
  },
  AvgVideoCaption_148014_Content_81 = {
    Text = "Звёздный кит наблюдает за нами"
  },
  AvgVideoCaption_148014_Content_82 = {
    Text = "Верующие"
  },
  AvgVideoCaption_148014_Content_83 = {
    Text = "Обнажите свои клинки"
  },
  AvgVideoCaption_148014_Content_84 = {
    Text = "Прими этот дар —"
  },
  AvgVideoCaption_148014_Content_85 = {
    Text = "Похоже, вы завершили чтение рун"
  },
  AvgVideoCaption_148014_Content_86 = {
    Text = "И людей достаточно… Хорошо"
  },
  AvgVideoCaption_148014_Content_87 = {
    Text = "Хорошо?"
  },
  AvgVideoCaption_148014_Content_88 = {
    Text = "Если бы не ожидание вас"
  },
  AvgVideoCaption_148014_Content_89 = {
    Text = "Я бы не стала вести столь скучные разговоры"
  },
  AvgVideoCaption_148014_Content_9 = {
    Text = "Его сила оказывает некоторое влияние на тех, чья воля недостаточно крепка…"
  },
  AvgVideoCaption_148014_Content_90 = {
    Text = "Моя привычка — позволять противнику обнажить клинок первым"
  },
  AvgVideoCaption_148014_Content_91 = {
    Text = "Теперь все приготовления завершены…"
  },
  AvgVideoCaption_148014_Content_92 = {
    Text = "Что?!… Эти цепи…"
  },
  AvgVideoCaption_148014_Content_93 = {
    Text = "Тебе нужны власть и богатство…"
  },
  AvgVideoCaption_148014_Content_94 = {
    Text = "Ты совершенно не понимаешь, что такое настоящая сила"
  },
  AvgVideoCaption_148014_Content_95 = {
    Text = "Однако"
  },
  AvgVideoCaption_148014_Content_96 = {
    Text = "Мой меч уже давно не видел достойного сражения"
  },
  AvgVideoCaption_148014_Content_97 = {
    Text = "Надеюсь, вы сможете доставить ему удовольствие"
  },
  AvgVideoCaption_148014_Content_98 = {
    Text = "Убейте её!"
  },
  AvgVideoCaption_148014_Content_99 = {
    Text = "Я давала тебе обещание…"
  },
  AvgVideoCaption_149925_Content_1 = {
    Text = "На вершине самой высокой снежной горы в мире"
  },
  AvgVideoCaption_149925_Content_10 = {
    Text = "Следуй за мной…"
  },
  AvgVideoCaption_149925_Content_11 = {
    Text = "Принеси в дар сокровища, желания и всё остальное!"
  },
  AvgVideoCaption_149925_Content_12 = {
    Text = "Твоё желание принято"
  },
  AvgVideoCaption_149925_Content_13 = {
    Text = "Всё остальное"
  },
  AvgVideoCaption_149925_Content_14 = {
    Text = "Предоставь богине снежной горы"
  },
  AvgVideoCaption_149925_Content_2 = {
    Text = "Там обитают боги"
  },
  AvgVideoCaption_149925_Content_3 = {
    Text = "Следуй за мной"
  },
  AvgVideoCaption_149925_Content_4 = {
    Text = "Богиня снежной горы исполнит твоё желание"
  },
  AvgVideoCaption_149925_Content_5 = {
    Text = "Вернуть ушедших…"
  },
  AvgVideoCaption_149925_Content_6 = {
    Text = "Семикратное богослужение"
  },
  AvgVideoCaption_149925_Content_7 = {
    Text = "Троекратный обет"
  },
  AvgVideoCaption_149925_Content_8 = {
    Text = "Жертвы для паломничества собраны"
  },
  AvgVideoCaption_149925_Content_9 = {
    Text = "Вершина уже близко"
  },
  AvgVideoCaption_149926_Content_1 = {
    Text = "У-у… господин…"
  },
  AvgVideoCaption_149926_Content_10 = {
    Text = "Отец каждый день напивался"
  },
  AvgVideoCaption_149926_Content_100 = {
    Text = "слёзы не помогают"
  },
  AvgVideoCaption_149926_Content_101 = {
    Text = "Итак, поговорим о тебе"
  },
  AvgVideoCaption_149926_Content_102 = {
    Text = "Ты следил за мной три квартала, не так ли?"
  },
  AvgVideoCaption_149926_Content_103 = {
    Text = "Ты заметил, какие у меня тонкие запястья, белая шея"
  },
  AvgVideoCaption_149926_Content_104 = {
    Text = "И как медленно я бегу с сумкой на плечах"
  },
  AvgVideoCaption_149926_Content_105 = {
    Text = "Счёты в твоей голове уже давно застучали"
  },
  AvgVideoCaption_149926_Content_106 = {
    Text = "Такая девочка"
  },
  AvgVideoCaption_149926_Content_107 = {
    Text = "На чёрном рынке за неё можно выручить хорошую цену"
  },
  AvgVideoCaption_149926_Content_108 = {
    Text = "Когда ты затащил меня в этот подвал"
  },
  AvgVideoCaption_149926_Content_109 = {
    Text = "Ты почувствовал, какая удача тебе улыбнулась?"
  },
  AvgVideoCaption_149926_Content_11 = {
    Text = "Мать каждый день плакала"
  },
  AvgVideoCaption_149926_Content_110 = {
    Text = "…Но, господин, ты не замечаешь"
  },
  AvgVideoCaption_149926_Content_111 = {
    Text = "Что в подвале, кажется, немного холоднее, чем снаружи?"
  },
  AvgVideoCaption_149926_Content_112 = {
    Text = "Хе-хе, хе-хе-хе-хе~"
  },
  AvgVideoCaption_149926_Content_113 = {
    Text = "Ничего страшного,"
  },
  AvgVideoCaption_149926_Content_114 = {
    Text = "Скоро тебе станет теплее, чем у печки"
  },
  AvgVideoCaption_149926_Content_115 = {
    Text = "Последнюю фразу истории"
  },
  AvgVideoCaption_149926_Content_116 = {
    Text = "По традиции должен произнести тот, кого съели"
  },
  AvgVideoCaption_149926_Content_117 = {Text = "Хи-хи~"},
  AvgVideoCaption_149926_Content_118 = {
    Text = "Давай же, господин, скажи мне —"
  },
  AvgVideoCaption_149926_Content_119 = {
    Text = "Тебе холодно?"
  },
  AvgVideoCaption_149926_Content_12 = {
    Text = "В доме не было огня в печи"
  },
  AvgVideoCaption_149926_Content_13 = {
    Text = "И не было хлеба"
  },
  AvgVideoCaption_149926_Content_14 = {
    Text = "Однажды зимой"
  },
  AvgVideoCaption_149926_Content_15 = {
    Text = "Снег намело до самого подоконника"
  },
  AvgVideoCaption_149926_Content_16 = {
    Text = "Меня выгнали из дома"
  },
  AvgVideoCaption_149926_Content_17 = {
    Text = "Только потому, что я рассказала Тёте Розе по соседству"
  },
  AvgVideoCaption_149926_Content_18 = {
    Text = "Что тот, кто меня избил — это папа"
  },
  AvgVideoCaption_149926_Content_19 = {
    Text = "Я шла и шла по снегу"
  },
  AvgVideoCaption_149926_Content_2 = {
    Text = "Прошу вас…"
  },
  AvgVideoCaption_149926_Content_20 = {
    Text = "Шла, пока обувь не промокла насквозь"
  },
  AvgVideoCaption_149926_Content_21 = {
    Text = "Пальцы на ногах онемели"
  },
  AvgVideoCaption_149926_Content_22 = {
    Text = "Как же холодно……"
  },
  AvgVideoCaption_149926_Content_23 = {
    Text = "Холодно……"
  },
  AvgVideoCaption_149926_Content_24 = {
    Text = "……А ты?"
  },
  AvgVideoCaption_149926_Content_25 = {
    Text = "Тебе тоже холодно?"
  },
  AvgVideoCaption_149926_Content_26 = {
    Text = "Этот ветер в погребе"
  },
  AvgVideoCaption_149926_Content_27 = {
    Text = "Будто пробирается прямо в кости……"
  },
  AvgVideoCaption_149926_Content_28 = {
    Text = "Правда ведь?"
  },
  AvgVideoCaption_149926_Content_29 = {
    Text = "Скажу тебе кое-что"
  },
  AvgVideoCaption_149926_Content_3 = {
    Text = "Отпустите меня"
  },
  AvgVideoCaption_149926_Content_30 = {
    Text = "Тогда было намного-намного холоднее, чем сейчас——"
  },
  AvgVideoCaption_149926_Content_31 = {
    Text = "Я всё шла"
  },
  AvgVideoCaption_149926_Content_32 = {Text = "Шла"},
  AvgVideoCaption_149926_Content_33 = {
    Text = "Слёзы, которые текли по щекам, превращались в лёд"
  },
  AvgVideoCaption_149926_Content_34 = {
    Text = "И когда я уже почти засыпала——"
  },
  AvgVideoCaption_149926_Content_35 = {
    Text = "Я услышала из-под сугроба"
  },
  AvgVideoCaption_149926_Content_36 = {
    Text = "Голос, который звал меня"
  },
  AvgVideoCaption_149926_Content_37 = {
    Text = "«Девочка, почему ты плачешь?»"
  },
  AvgVideoCaption_149926_Content_38 = {
    Text = "«Потому что ты сказала правду?»"
  },
  AvgVideoCaption_149926_Content_39 = {
    Text = "«Потому что ты слишком честная»"
  },
  AvgVideoCaption_149926_Content_4 = {
    Text = "Я никому не расскажу об этом…"
  },
  AvgVideoCaption_149926_Content_40 = {
    Text = "«Вот тебя и бросили здесь?»"
  },
  AvgVideoCaption_149926_Content_41 = {
    Text = "Я молчала"
  },
  AvgVideoCaption_149926_Content_42 = {
    Text = "Потому что даже губы не могла разомкнуть"
  },
  AvgVideoCaption_149926_Content_43 = {
    Text = "Но оно сказало:"
  },
  AvgVideoCaption_149926_Content_44 = {
    Text = "«Ничего страшного»"
  },
  AvgVideoCaption_149926_Content_45 = {
    Text = "«Я научу тебя одному языку»"
  },
  AvgVideoCaption_149926_Content_46 = {
    Text = "«Скажи это — и тебе больше никогда не будет холодно»"
  },
  AvgVideoCaption_149926_Content_47 = {
    Text = "И тогда я"
  },
  AvgVideoCaption_149926_Content_48 = {
    Text = "выучила свою первую ложь"
  },
  AvgVideoCaption_149926_Content_49 = {
    Text = "С помощью этой лжи"
  },
  AvgVideoCaption_149926_Content_5 = {
    Text = "Я отдам вам всё, что у меня есть"
  },
  AvgVideoCaption_149926_Content_50 = {
    Text = "я постучалась в первый крестьянский дом"
  },
  AvgVideoCaption_149926_Content_51 = {
    Text = "и выманила одно яблоко"
  },
  AvgVideoCaption_149926_Content_52 = {
    Text = "Я откусила лишь один раз"
  },
  AvgVideoCaption_149926_Content_53 = {
    Text = "Остальное"
  },
  AvgVideoCaption_149926_Content_54 = {
    Text = "отдала тому голосу"
  },
  AvgVideoCaption_149926_Content_55 = {
    Text = "Знаешь ли ты"
  },
  AvgVideoCaption_149926_Content_56 = {
    Text = "когда человек почти замерзает насмерть"
  },
  AvgVideoCaption_149926_Content_57 = {
    Text = "всё тело вдруг охватывает жар"
  },
  AvgVideoCaption_149926_Content_58 = {
    Text = "теплее, чем любая печь на свете"
  },
  AvgVideoCaption_149926_Content_59 = {
    Text = "С того самого момента"
  },
  AvgVideoCaption_149926_Content_6 = {
    Text = "Не продавайте меня, пожалуйста?"
  },
  AvgVideoCaption_149926_Content_60 = {
    Text = "мне больше никогда не было холодно"
  },
  AvgVideoCaption_149926_Content_61 = {
    Text = "Оно говорило"
  },
  AvgVideoCaption_149926_Content_62 = {
    Text = "Оно лишь «учило» меня"
  },
  AvgVideoCaption_149926_Content_63 = {
    Text = "Я учился быстро"
  },
  AvgVideoCaption_149926_Content_64 = {
    Text = "Обманом добытого становилось всё больше"
  },
  AvgVideoCaption_149926_Content_65 = {
    Text = "Словно маленькие горы"
  },
  AvgVideoCaption_149926_Content_66 = {
    Text = "Заполнившие весь дом"
  },
  AvgVideoCaption_149926_Content_67 = {
    Text = "Но потом"
  },
  AvgVideoCaption_149926_Content_68 = {
    Text = "Я постепенно начал замечать"
  },
  AvgVideoCaption_149926_Content_69 = {
    Text = "Что с каждой ложью"
  },
  AvgVideoCaption_149926_Content_7 = {
    Text = "Прошу вас"
  },
  AvgVideoCaption_149926_Content_70 = {
    Text = "Я всё меньше помню, каким был раньше"
  },
  AvgVideoCaption_149926_Content_71 = {
    Text = "Первым забылось"
  },
  AvgVideoCaption_149926_Content_72 = {
    Text = "Как отец в пьяном угаре бил кулаком по столу"
  },
  AvgVideoCaption_149926_Content_73 = {
    Text = "Потом — заплаканное лицо матери"
  },
  AvgVideoCaption_149926_Content_74 = {
    Text = "А ещё позже"
  },
  AvgVideoCaption_149926_Content_75 = {
    Text = "Моё собственное имя"
  },
  AvgVideoCaption_149926_Content_76 = {
    Text = "Я и сам когда-то думал"
  },
  AvgVideoCaption_149926_Content_77 = {
    Text = "Что так продолжаться не должно"
  },
  AvgVideoCaption_149926_Content_78 = {
    Text = "Но каждый раз, когда я только начинал так думать"
  },
  AvgVideoCaption_149926_Content_79 = {
    Text = "Оно тихо шептало мне на ухо —"
  },
  AvgVideoCaption_149926_Content_8 = {
    Text = "Пожалейте меня…"
  },
  AvgVideoCaption_149926_Content_80 = {
    Text = "『Холодно? Хочешь, чтобы стало теплее?』"
  },
  AvgVideoCaption_149926_Content_81 = {
    Text = "А потом я"
  },
  AvgVideoCaption_149926_Content_82 = {
    Text = "снова произнесла фразу"
  },
  AvgVideoCaption_149926_Content_83 = {
    Text = "ещё одну, и ещё"
  },
  AvgVideoCaption_149926_Content_84 = {
    Text = "и ещё одну, слово за словом"
  },
  AvgVideoCaption_149926_Content_85 = {
    Text = "так просто, так легко"
  },
  AvgVideoCaption_149926_Content_86 = {
    Text = "так легко вытекало из снега"
  },
  AvgVideoCaption_149926_Content_87 = {
    Text = "тёплое и сладкое"
  },
  AvgVideoCaption_149926_Content_88 = {
    Text = "кто же я такая,"
  },
  AvgVideoCaption_149926_Content_89 = {
    Text = "я ли это?"
  },
  AvgVideoCaption_149926_Content_9 = {
    Text = "Меня никогда не любили с детства"
  },
  AvgVideoCaption_149926_Content_90 = {
    Text = "Голос под снегом"
  },
  AvgVideoCaption_149926_Content_91 = {
    Text = "с самого начала"
  },
  AvgVideoCaption_149926_Content_92 = {
    Text = "был моим собственным голосом, правда?"
  },
  AvgVideoCaption_149926_Content_93 = {
    Text = "Ах, не убегайте, господин"
  },
  AvgVideoCaption_149926_Content_94 = {
    Text = "бежать уже поздно"
  },
  AvgVideoCaption_149926_Content_95 = {
    Text = "ваши руки и ноги"
  },
  AvgVideoCaption_149926_Content_96 = {
    Text = "давно уже онемели от холода"
  },
  AvgVideoCaption_149926_Content_97 = {
    Text = "хотите, мы поможем вам согреться?"
  },
  AvgVideoCaption_149926_Content_98 = {
    Text = "не плачьте"
  },
  AvgVideoCaption_149926_Content_99 = {
    Text = "я пробовала"
  },
  AvgVideoCaption_18618_Content_1 = {
    Text = "В глубине тайной комнаты, белый монстр стоит в полной тишине."
  },
  AvgVideoCaption_18619_Content_1 = {
    Text = "Безумие постепенно исчезало из глаз Ротань, уступая место тусклому оттенку, испещренному серебристым сиянием."
  },
  AvgVideoCaption_18619_Content_2 = {
    Text = "Пришедшая в сознание Ротань, словно от сильной головной боли, держась за лоб одной рукой, опустила голову."
  },
  AvgVideoCaption_18620_Content_1 = {
    Text = "С её словами все существа, нарушающие законы природы, исчезли в мгновение ока."
  },
  AvgVideoCaption_18621_Content_1 = {
    Text = "Она подняла руку и протерла стекло перед собой."
  },
  AvgVideoCaption_18622_Content_1 = {
    Text = "Золотистые лучи заката проникают через огромный прозрачный циферблат колокольни, падая на девочку."
  },
  AvgVideoCaption_18623_Content_1 = {
    Text = "Снова остался в одиночестве."
  },
  AvgVideoCaption_18624_Content_1 = {
    Text = "В следующий момент зловещее видение исчезло."
  },
  AvgVideoCaption_18625_Content_1 = {
    Text = "Перед теми огромными и неизвестно сущностями.."
  },
  AvgVideoCaption_18625_Content_10 = {
    Text = "Слыша это слово, в голове раздаётся сильный звон, сопровождаемый болью, пронзающей глубину мозга."
  },
  AvgVideoCaption_18625_Content_11 = {
    Text = "Желудок переворачивается, а резкий запах рвотных масс Удар в нос."
  },
  AvgVideoCaption_18625_Content_2 = {
    Text = "Человек так мал."
  },
  AvgVideoCaption_18625_Content_3 = {
    Text = "Это сон?"
  },
  AvgVideoCaption_18625_Content_4 = {
    Text = "В груди поднялось сильное Беспокойство, как волна."
  },
  AvgVideoCaption_18625_Content_5 = {
    Text = "—Святилище ключей Университета Мисаг, церемония вручения серебряного ключа—"
  },
  AvgVideoCaption_18625_Content_6 = {
    Text = "«...Университет Мисаг был пионером в борьбе с @2...»"
  },
  AvgVideoCaption_18625_Content_7 = {
    Text = "«...стать следователем в Университете Мисаг,»"
  },
  AvgVideoCaption_18625_Content_8 = {
    Text = "«Это означает, что ваша оставшаяся жизнь будет наполнена смертью и сумасшествием...»"
  },
  AvgVideoCaption_18625_Content_9 = {
    Text = "«За последние десять лет, распространение@2...»"
  },
  AvgVideoCaption_18626_Content_1 = {
    Text = "Чтобы обеспечить безопасность всех сейчас, я тоже чувствую себя удовлетворённым и счастливым."
  },
  AvgVideoCaption_18626_Content_10 = {
    Text = "Пальцы ощущают влажность, но без ощущения реального контакта."
  },
  AvgVideoCaption_18626_Content_11 = {
    Text = "Небольшая часть реальности рассеялась у неё под кончиками пальцев, навсегда исчезнув из этого мира."
  },
  AvgVideoCaption_18626_Content_2 = {
    Text = "Я больше не позволю себя контролировать."
  },
  AvgVideoCaption_18626_Content_3 = {
    Text = "Не причинит больше урона никому."
  },
  AvgVideoCaption_18626_Content_4 = {
    Text = "Не позволю больше друзьям умирать из-за меня."
  },
  AvgVideoCaption_18626_Content_5 = {
    Text = "Прикрываясь звоном колокола, Ай Джис каким-то образом легко открыла наглухо закрытое стекло."
  },
  AvgVideoCaption_18626_Content_6 = {
    Text = "Извините меня, Дженкинса."
  },
  AvgVideoCaption_18626_Content_7 = {
    Text = "Передай ей, что мы всегда будем друзьями."
  },
  AvgVideoCaption_18626_Content_8 = {
    Text = "Ай Джис закрыла глаза и почувствовала, что её тело стало невесомым, словно перышко. За её спиной Рамона в порыве надежды протянула руку к ночному небу."
  },
  AvgVideoCaption_18626_Content_9 = {
    Text = "Контакт, схватить."
  },
  AvgVideoCaption_22146_Content_1 = {
    Text = "Ужасное бедствие наступило"
  },
  AvgVideoCaption_22146_Content_2 = {
    Text = "«Раствориться»"
  },
  AvgVideoCaption_22146_Content_3 = {
    Text = "Оно в состоянии поглощения всего"
  },
  AvgVideoCaption_22146_Content_4 = {
    Text = "Даже память не может ускользнуть из его рук"
  },
  AvgVideoCaption_22146_Content_5 = {
    Text = "Прошло несколько веков, и наконец мы нашёл прорыв——"
  },
  AvgVideoCaption_22146_Content_6 = {
    Text = "«Сердечник из серебра»"
  },
  AvgVideoCaption_22146_Content_7 = {
    Text = "Оно может вызвать пробуждение умерших духов"
  },
  AvgVideoCaption_22146_Content_8 = {
    Text = "Эти духи - наша последняя надежда"
  },
  AvgVideoCaption_22146_Content_9 = {
    Text = "По крайней мере, мы так надеемся.."
  },
  AvgVideoCaption_24281_Content_1 = {
    Text = "Наконец настал момент расцвета."
  },
  AvgVideoCaption_24724_Content_1 = {
    Text = "Количество раз неудач не имеет значения"
  },
  AvgVideoCaption_24724_Content_2 = {
    Text = "Независимо от того, сколько раз я вернусь, я обязательно найду это"
  },
  AvgVideoCaption_24724_Content_3 = {
    Text = "Спаса́ем этот мир"
  },
  AvgVideoCaption_24724_Content_4 = {
    Text = "Метод, чтобы спасти тебя"
  },
  AvgVideoCaption_36151_Content_1 = {
    Text = "Выход, Выход там.."
  },
  AvgVideoCaption_36151_Content_10 = {
    Text = "Внемлите, о Господин!"
  },
  AvgVideoCaption_36151_Content_11 = {
    Text = "Почему я должен слушаться!"
  },
  AvgVideoCaption_36151_Content_12 = {
    Text = "Вернись ко мне, Господь"
  },
  AvgVideoCaption_36151_Content_13 = {
    Text = "Почему мы должны подчиняться!"
  },
  AvgVideoCaption_36151_Content_14 = {
    Text = "Пожертвование жизни! Воссоздание божественной страны ——"
  },
  AvgVideoCaption_36151_Content_15 = {
    Text = "Что за божественная страна, что за бог... и какое мне до этого дело!"
  },
  AvgVideoCaption_36151_Content_16 = {
    Text = "Пожертвование жизни! Вернуться моему господину——"
  },
  AvgVideoCaption_36151_Content_17 = {
    Text = "Покинем это место. Вместе... уйдём отсюда!"
  },
  AvgVideoCaption_36151_Content_2 = {
    Text = "Божественная Матушка-Матушка, почему уходишь?"
  },
  AvgVideoCaption_36151_Content_3 = {
    Text = "Не надо... Я не хочу быть какой-то богиней"
  },
  AvgVideoCaption_36151_Content_4 = {
    Text = "Я не надо быть жертвенным предложением.."
  },
  AvgVideoCaption_36151_Content_5 = {
    Text = "Божье царство даст тебе жизнь"
  },
  AvgVideoCaption_36151_Content_6 = {
    Text = "Ещё как далеко? Ещё сколько времени?"
  },
  AvgVideoCaption_36151_Content_7 = {
    Text = "Звёзды сошлись настал——"
  },
  AvgVideoCaption_36151_Content_8 = {
    Text = "Уже...поздно?"
  },
  AvgVideoCaption_36151_Content_9 = {
    Text = "Но... за что?!"
  },
  AvgVideoCaption_45044_Content_1 = {
    Text = "Невидимая Чума прибыла"
  },
  AvgVideoCaption_45044_Content_10 = {
    Text = "«Ты готов отдать свою Каро за нас?»"
  },
  AvgVideoCaption_45044_Content_11 = {
    Text = "«Ты готов отдать свою жизнь за нас?»"
  },
  AvgVideoCaption_45044_Content_12 = {
    Text = "«Отец Небесный плачет за нас, своих детей.»"
  },
  AvgVideoCaption_45044_Content_13 = {
    Text = "«Он хочет, чтобы мы, благородные, были Его исполнителями»"
  },
  AvgVideoCaption_45044_Content_14 = {
    Text = "«Пусть страдания исчезнут с этой земли.»"
  },
  AvgVideoCaption_45044_Content_15 = {
    Text = "Я являюсь исполнителем воли Отца-Бога"
  },
  AvgVideoCaption_45044_Content_16 = {
    Text = "Непременно сделаю всё возможное"
  },
  AvgVideoCaption_45044_Content_17 = {
    Text = "«Почему, епископ, почему сегодня нет благословения?»"
  },
  AvgVideoCaption_45044_Content_18 = {
    Text = "«Почему ты не продолжаешь? Почему не спасаешь нас?»"
  },
  AvgVideoCaption_45044_Content_19 = {
    Text = "«Как ты можешь быть бессильным?»"
  },
  AvgVideoCaption_45044_Content_2 = {
    Text = "Оно приносит смерть, приносит отчаяние"
  },
  AvgVideoCaption_45044_Content_20 = {
    Text = "«Ты отказаться от нас, позволил страданию распространиться!»"
  },
  AvgVideoCaption_45044_Content_21 = {
    Text = "«Я хочу благословения, я хочу жить, я хочу жить!»"
  },
  AvgVideoCaption_45044_Content_22 = {
    Text = "«недостаточно, недостаточно, недостаточно!»"
  },
  AvgVideoCaption_45044_Content_23 = {
    Text = "Моя жизнь"
  },
  AvgVideoCaption_45044_Content_24 = {
    Text = "Стремятся освободить вас от горестей и страданий"
  },
  AvgVideoCaption_45044_Content_25 = {
    Text = "Пастырь душ"
  },
  AvgVideoCaption_45044_Content_26 = {
    Text = "Всё, чтобы обеспечить ваше благо"
  },
  AvgVideoCaption_45044_Content_3 = {
    Text = "О, дети Отца-бога"
  },
  AvgVideoCaption_45044_Content_4 = {
    Text = "Мои братья и сёстры"
  },
  AvgVideoCaption_45044_Content_5 = {
    Text = "Ваши страдания, я разделяю"
  },
  AvgVideoCaption_45044_Content_6 = {
    Text = "Я готов отдать всё"
  },
  AvgVideoCaption_45044_Content_7 = {
    Text = "Лишь для того, чтобы вы перестали страдать"
  },
  AvgVideoCaption_45044_Content_8 = {
    Text = "«Епископ Сальвадор, сегодня вы дадите нам благословение?»"
  },
  AvgVideoCaption_45044_Content_9 = {
    Text = "«Епископ Сальвадора, вы спасёте нас?»"
  },
  AvgVideoCaption_50040_Content_1 = {
    Text = "Размножение, это часть этого первозданного пустынного ландшафта"
  },
  AvgVideoCaption_50040_Content_10 = {
    Text = "Слиться со мной воедино"
  },
  AvgVideoCaption_50040_Content_11 = {
    Text = "Завести потомство со мной"
  },
  AvgVideoCaption_50040_Content_12 = {
    Text = "Пусть наша кровь и наследие"
