    Text = "Главный способ выжить"
  },
  AvgVideoCaption_50040_Content_21 = {
    Text = "Ты хочешь"
  },
  AvgVideoCaption_50040_Content_22 = {
    Text = "Присоединяйтесь?"
  },
  AvgVideoCaption_50040_Content_23 = {
    Text = "Матушка миллиона отпрысков"
  },
  AvgVideoCaption_50040_Content_3 = {
    Text = "Ты хочешь присоединиться?"
  },
  AvgVideoCaption_50040_Content_4 = {
    Text = "Приходи"
