  AvgVideoCaption_50040_Content_8 = {
    Text = "Касайся меня"
  },
  AvgVideoCaption_50040_Content_9 = {
    Text = "Введите в меня"
  },
  AvgVideoCaption_56358_Content_1 = {
    Text = "Дождь, это прощание облаков с небом"
