  AvgVideoCaption_56358_Content_10 = {
    Text = "Ты весна"
  },
  AvgVideoCaption_56358_Content_11 = {
    Text = "Подари мне песню"
  },
  AvgVideoCaption_56358_Content_12 = {
    Text = "Весеннее стихотворение, подаренное саду"
  },
  AvgVideoCaption_56358_Content_13 = {
    Text = "В нашей пустынной жизни ярко-красная роза поселяется"
  },
  AvgVideoCaption_56358_Content_14 = {
    Text = "«Возьми меня за руку», — сказал ты"
  },
  AvgVideoCaption_56358_Content_15 = {
    Text = "Когда наши пальцы соприкоснутся, ты подаришь мне цветущий сад"
  },
  AvgVideoCaption_56358_Content_16 = {
    Text = "В нашем маленьком королевстве"
  },
  AvgVideoCaption_56358_Content_17 = {
    Text = "Ты будешь нести для меня все тернии"
  },
  AvgVideoCaption_56358_Content_18 = {
    Text = "Прими эти стихи, которые весна посвящает саду"
  },
  AvgVideoCaption_56358_Content_19 = {
    Text = "В нашей пустынной жизни ярко-красная роза поселяется"
  },
  AvgVideoCaption_56358_Content_2 = {
    Text = "Когда мы снова встретимся, я принесу букет"
