  AvgVideoCaption_70276_Content_14 = {
    Text = "Призывай меня по имени, даже если прощание близко"
  },
  AvgVideoCaption_70276_Content_15 = {
    Text = "Всё ещё верит в смысл поиска и передвигаться вперёд"
  },
  AvgVideoCaption_70276_Content_16 = {
    Text = "Зови моё имя, даже если время остановится"
  },
  AvgVideoCaption_70276_Content_17 = {
    Text = "Всё ещё нужно пробудить вечную надежду"
  },
  AvgVideoCaption_70276_Content_18 = {
    Text = "Могу ли я призывать тебя по имени, даже если мир исчезает"
  },
  AvgVideoCaption_70276_Content_19 = {
    Text = "Продолжать держать миг ослепительного сияния"
  },
  AvgVideoCaption_70276_Content_2 = {
    Text = "Из забытого мира"
  },
  AvgVideoCaption_70276_Content_20 = {
    Text = "Да направит нас Серебряный ключ"
  },
  AvgVideoCaption_70276_Content_21 = {
    Text = "Да направит нас Серебряный ключ"
  },
  AvgVideoCaption_70276_Content_3 = {
    Text = "Гребя тихими веслами"
  },
  AvgVideoCaption_70276_Content_4 = {
    Text = "Взгляд вдаль на недостижимые высоты"
  },
  AvgVideoCaption_70276_Content_5 = {
    Text = "Серебряная звезда утренней зари поглощена чёрной волной"
  },
  AvgVideoCaption_70276_Content_6 = {
    Text = "Размытая запись — забытое лицо"
  },
  AvgVideoCaption_70276_Content_7 = {
    Text = "Пытаясь изо всех сил поймать, но всё же не в силах удержать"
  },
  AvgVideoCaption_70276_Content_8 = {
    Text = "В постепенно тающей полярной ночи изливается последнее желание"
  },
  AvgVideoCaption_70276_Content_9 = {
    Text = "До рассвета забвения"
  },
  AvgVideoCaption_72086_Content_1 = {
    Text = "Посмотри вверх"
  },
  AvgVideoCaption_72086_Content_10 = {
    Text = "Вовсе не её намерением было ничто"
  },
  AvgVideoCaption_72086_Content_11 = {
    Text = "Безумие знания заставило её собственными руками запустить двигатель уничтожения"
  },
  AvgVideoCaption_72086_Content_12 = {
    Text = "Она – путеводитель по Лесу Души"
  },
  AvgVideoCaption_72086_Content_13 = {
    Text = "Под маятником, который вечно качается"
  },
  AvgVideoCaption_72086_Content_14 = {
    Text = "Страдающая душа извергает мрачные глубины внутренностей изнутри"
  },
  AvgVideoCaption_72086_Content_15 = {
    Text = "Эстетика живых существ давно утратила свою чистоту"
  },
  AvgVideoCaption_72086_Content_16 = {
    Text = "Под предначертанным ножом, он ведёт свой танец среди покойных"
  },
  AvgVideoCaption_72086_Content_17 = {
    Text = "Потомок богов, Матушка богов"
  },
  AvgVideoCaption_72086_Content_18 = {
    Text = "В честь рождения божественного короля предлагаем извивающуюся плоть и кровь"
  },
  AvgVideoCaption_72086_Content_19 = {
    Text = "Вкушайте безграничное величие"
  },
  AvgVideoCaption_72086_Content_2 = {
    Text = "Звёзды сошлись Звёзд приближается"
  },
  AvgVideoCaption_72086_Content_20 = {
    Text = "Тысячи ледников, ослепительно-белые снежные равнины"
  },
  AvgVideoCaption_72086_Content_21 = {
    Text = "Она воплощение чистейшей белизны"
  },
  AvgVideoCaption_72086_Content_22 = {
    Text = "...Ты поверишь таким бредовым словам?"
  },
  AvgVideoCaption_72086_Content_23 = {
    Text = "Воспевай, стенай, плети паутину словами"
  },
  AvgVideoCaption_72086_Content_24 = {
    Text = "На её челноке"
  },
  AvgVideoCaption_72086_Content_25 = {
    Text = "Люди, соединённые нитями"
  },
  AvgVideoCaption_72086_Content_26 = {
    Text = "Все мы — игрушки судьбы"
  },
  AvgVideoCaption_72086_Content_27 = {
    Text = "Завершить задание в этом месте"
  },
  AvgVideoCaption_72086_Content_28 = {
    Text = "Вернись же в исходный мир"
  },
  AvgVideoCaption_72086_Content_29 = {
    Text = "Сон без причины уже прекратился"
  },
  AvgVideoCaption_72086_Content_3 = {
    Text = "Из мира, который уже встретил «Конец Всего»"
  },
  AvgVideoCaption_72086_Content_30 = {
    Text = "Под управлением Юй, Лемурия стала вечной и неисчезающей королевской землёй"
  },
  AvgVideoCaption_72086_Content_31 = {
    Text = "Посмотри вверх"
  },
  AvgVideoCaption_72086_Content_32 = {
    Text = "Настал момент правильной позиции"
  },
  AvgVideoCaption_72086_Content_4 = {
    Text = "Дорогой Гость, прибывший Издалека"
  },
  AvgVideoCaption_72086_Content_5 = {
    Text = "Тупое создание уже обратилось в Пепел"
  },
  AvgVideoCaption_72086_Content_6 = {
    Text = "Используя ваш разум"
  },
  AvgVideoCaption_72086_Content_7 = {
    Text = "Поддерживайте путь жизни"
  },
  AvgVideoCaption_72086_Content_8 = {
    Text = "Ради истинного прибытия бога-короля"
  },
  AvgVideoCaption_72086_Content_9 = {
    Text = "Отдать всю свою духовность и сновидения"
  },
  AvgVideoCaption_76210_Content_1 = {
    Text = "Венкор, включи, пожалуйста, граммофон"
  },
  AvgVideoCaption_76210_Content_10 = {
    Text = "Текущая лучшая стратегия – провести операцию на этой мозговой капсуле и модифицировать её интерфейс для соединения с питательным раствором"
  },
  AvgVideoCaption_76210_Content_11 = {
    Text = "Принудительное повышение активности мозга, активируя сознание Хранителя тайн"
  },
  AvgVideoCaption_76210_Content_12 = {
    Text = "Дорогой щенок, не бойся, пожалуйста"
  },
  AvgVideoCaption_76210_Content_13 = {
    Text = "Хорошо, приборы готовы, выходи"
  },
  AvgVideoCaption_76210_Content_14 = {
    Text = "Какие красивые извилины"
  },
  AvgVideoCaption_76210_Content_15 = {
    Text = "Удалить лишние примеси.."
  },
  AvgVideoCaption_76210_Content_16 = {
    Text = "Очищение коры головного мозга"
  },
  AvgVideoCaption_76210_Content_17 = {
    Text = "Здесь.."
  },
  AvgVideoCaption_76210_Content_18 = {
    Text = "Хвостатое ядро"
  },
  AvgVideoCaption_76210_Content_19 = {
    Text = "Бобовидное ядро"
  },
  AvgVideoCaption_76210_Content_2 = {
    Text = "Его сознание ещё не может нормально подключиться к мозговому контейнеру?"
  },
  AvgVideoCaption_76210_Content_20 = {
    Text = "Миндальное тело"
  },
  AvgVideoCaption_76210_Content_21 = {
    Text = "Ядра экрана.."
  },
  AvgVideoCaption_76210_Content_22 = {
    Text = "Всё функции работают нормально"
  },
  AvgVideoCaption_76210_Content_23 = {
    Text = "Дорогой щенок, я буду осторожно защищать твой мозг"
  },
  AvgVideoCaption_76210_Content_24 = {
    Text = "Если повредить гиппокамп, из-за чего будут потеряны драгоценные памяти между тобой и мной, будет очень жаль"
  },
  AvgVideoCaption_76210_Content_25 = {
    Text = "Я ещё помню тот день, когда мы встретились впервые, ты принял меня за дора"
  },
  AvgVideoCaption_76210_Content_26 = {
    Text = "Ты смотришь на меня, твой звук дрожит, когда ты зовёшь меня «Профессор дора»"
  },
  AvgVideoCaption_76210_Content_27 = {
    Text = "Я думал, что выгляжу внушительно, оказалось, ты не завершил отчёт по внешней работе и боишься, что она тебя отругает"
  },
  AvgVideoCaption_76210_Content_28 = {
    Text = "Этот Фрагмент памяти, где он находится в твоем мозгу?"
  },
  AvgVideoCaption_76210_Content_29 = {
    Text = "Здесь?"
  },
  AvgVideoCaption_76210_Content_3 = {
    Text = "Всего лишь стыковка между размерностями, неужели это для тебя такая Сложный?"
  },
  AvgVideoCaption_76210_Content_30 = {
    Text = "...ещё здесь?"
  },
  AvgVideoCaption_76210_Content_31 = {
    Text = "Ха, всё в порядке. Всё равно, где бы это ни было"
  },
  AvgVideoCaption_76210_Content_32 = {
    Text = "Ведь есть более важные дела"
  },
  AvgVideoCaption_76210_Content_33 = {
    Text = "В тот день, в конце, ты и профессор Мисаг лично запечатали меня в темной подземной глубине"
  },
  AvgVideoCaption_76210_Content_34 = {
    Text = "Все четыре конечности скованы ограничителями, диапазон движений настолько узкий, что даже повернуться сложно.."
  },
  AvgVideoCaption_76210_Content_35 = {
    Text = "Даже если ты забыл.."
  },
  AvgVideoCaption_76210_Content_36 = {
    Text = "Я никогда, никогда не забуду!"
  },
  AvgVideoCaption_76210_Content_37 = {
    Text = "Вечно падай в ад бездны!"
  },
  AvgVideoCaption_76210_Content_38 = {
    Text = "Не Беспокойство, я восстановился"
  },
  AvgVideoCaption_76210_Content_39 = {
    Text = "Извините, Мисаг и её щенок"
  },
  AvgVideoCaption_76210_Content_4 = {
    Text = "Раньше думал, что ▼▼технологии всю жизнь посвятили исследованию переноса сознания, такая мелочь для них точно не проблема"
  },
  AvgVideoCaption_76210_Content_40 = {
    Text = "Не стоило так сильно волноваться"
  },
  AvgVideoCaption_76210_Content_41 = {
    Text = "Следующим шагом я хочу перерезать тебе ствол мозга"
  },
  AvgVideoCaption_76210_Content_42 = {
    Text = "Достигнуть твоего гипоталамуса, настроить твой мезенцефалон.."
  },
  AvgVideoCaption_76210_Content_43 = {
    Text = "Ох, твои нервы дергаются"
  },
  AvgVideoCaption_76210_Content_44 = {
    Text = "Как жалко, не стоит ли мне ввести немного обезболивающего?"
  },
  AvgVideoCaption_76210_Content_45 = {
    Text = "Жаль, но сейчас уже слишком поздно"
  },
  AvgVideoCaption_76210_Content_46 = {
    Text = "Подожди ещё немного, скоро, скоро уже ——"
  },
  AvgVideoCaption_76210_Content_47 = {
    Text = "Хм-хм, посмотрим"
  },
  AvgVideoCaption_76210_Content_48 = {
    Text = "Где это?"
  },
  AvgVideoCaption_76210_Content_49 = {Text = "Нашёл"},
  AvgVideoCaption_76210_Content_5 = {
    Text = "Похоже, я ещё переоценил тебя"
  },
  AvgVideoCaption_76210_Content_50 = {
    Text = "Хм, чтобы восстановить активность, нужно немного электрошоковой стимуляции"
  },
  AvgVideoCaption_76210_Content_51 = {
    Text = "Я пойду принесу электрошокер, сам будь осторожен, хорошо"
  },
  AvgVideoCaption_76210_Content_52 = {
    Text = "Прости, что заставил ждать, бедный малыш"
  },
  AvgVideoCaption_76210_Content_53 = {
    Text = "Я заставлю тебя хорошо прочувствовать.."
  },
  AvgVideoCaption_76210_Content_54 = {
    Text = "Такой же глубокий, насыщенный... как чернила.."
  },
  AvgVideoCaption_76210_Content_55 = {
    Text = "Сейчас, давайте начнем с самого низкого уровня"
  },
  AvgVideoCaption_76210_Content_56 = {
    Text = "Хотя я больше склоняюсь к эффективной, мгновенной смерти"
  },
  AvgVideoCaption_76210_Content_57 = {
    Text = "Но сейчас настал момент, чтобы ты хорошо «наслаждался» Я не упущу этот шанс"
  },
  AvgVideoCaption_76210_Content_58 = {
    Text = "В первый день, когда я получил плиту, мне казалось, что это просто пустая выдумка"
  },
  AvgVideoCaption_76210_Content_59 = {
    Text = "Однако, я всего лишь прочитала первую строку"
  },
  AvgVideoCaption_76210_Content_6 = {
    Text = "Ничего не поделаешь, я сам возьмусь за это"
  },
  AvgVideoCaption_76210_Content_60 = {
    Text = "Не...полдела"
  },
  AvgVideoCaption_76210_Content_61 = {
    Text = "Я сразу понял, что это Реальность предмет"
  },
  AvgVideoCaption_76210_Content_62 = {
    Text = "Эйфория охватила меня"
  },
  AvgVideoCaption_76210_Content_63 = {
    Text = "Позволь мне описать это ощущение. Оно точно такое же, как у тебя сейчас"
  },
  AvgVideoCaption_76210_Content_64 = {
    Text = "Почти незаметное, де, исходящее откуда-то, слабое Паралич"
  },
  AvgVideoCaption_76210_Content_65 = {
    Text = "Я не уловил признаков надвигающегося кризиса, даже наоборот, чувствовал себя довольно комфортно.."
  },
  AvgVideoCaption_76210_Content_66 = {
    Text = "Конечно! Правда мира, возможно, Лечение, который я ищу, прямо передо мной"
  },
  AvgVideoCaption_76210_Content_67 = {
    Text = "Как будто соблазненный мёдом, я, не осознавая того, с жадностью продолжал читать"
  },
  AvgVideoCaption_76210_Content_68 = {
    Text = "Шаг за шагом приближаясь к той самой окончательной ловушке.."
  },
  AvgVideoCaption_76210_Content_69 = {
    Text = "Я угодил в ловушка"
  },
  AvgVideoCaption_76210_Content_7 = {
    Text = "Щенок Мисаг, это большая честь для тебя"
  },
  AvgVideoCaption_76210_Content_70 = {
    Text = "Ловушка, созданная специально для я, для этого высокомерного и лживого гения!"
  },
  AvgVideoCaption_76210_Content_71 = {
    Text = "Да! Именно в центре той плиты, огромная ловушка уже давно ждёт!"
  },
  AvgVideoCaption_76210_Content_72 = {
    Text = "Я Шаг за шагом, почти со слезами радости подошёл!"
  },
  AvgVideoCaption_76210_Content_73 = {
    Text = "Когда я понял, что означает прочитанное мной, было уже слишком поздно!"
  },
  AvgVideoCaption_76210_Content_74 = {
    Text = "Я знаю всё! Я знаю Лечение! Я знаю ▼▼!!"
  },
  AvgVideoCaption_76210_Content_75 = {
    Text = "Вы почувствовали это?"
  },
  AvgVideoCaption_76210_Content_76 = {
    Text = "Эта острая, пронизывающая боль, это невыносимое отчаяние!"
  },
  AvgVideoCaption_76210_Content_77 = {
    Text = "Безумие, черное де отчаяние!"
  },
  AvgVideoCaption_76210_Content_78 = {
    Text = "Извините, щенок Мисаг, я снова не смог контролировать свои эмоции"
  },
  AvgVideoCaption_76210_Content_79 = {
    Text = "Не волнуйся, хотя метод и грубоват одна точка, но базовая активность точно соответствует стандарту"
  },
  AvgVideoCaption_76210_Content_8 = {
    Text = "Уже выяснена конкретная проблема: выбранная вами активность мозгового цилиндра недостаточна для поддержания сознания Хранителя тайн Мисаг"
  },
  AvgVideoCaption_76210_Content_80 = {
    Text = "Сейчас я помогу подключить датчик"
  },
  AvgVideoCaption_76210_Content_81 = {
    Text = "Скоро ты придёшь в этот мир"
  },
  AvgVideoCaption_76210_Content_82 = {
    Text = "Далее, ждём момента, когда ты проснёшься, и посмотрим, как ты встретишь свою внешность"
  },
  AvgVideoCaption_76210_Content_83 = {
    Text = "Я с нетерпением жду наступления этого дня"
  },
  AvgVideoCaption_76210_Content_9 = {
    Text = "Но повторный перенос связан с повышенным риском потери осознания"
  },
  AvgVideoCaption_81062_Content_1 = {
    Text = "Дорогая, следуй за мной"
  },
  AvgVideoCaption_81062_Content_10 = {
    Text = "Листья шуршат под вашими ногами"
  },
  AvgVideoCaption_81062_Content_11 = {
    Text = "Ваше дыхание стало ли легче, чем три секунды назад?"
  },
  AvgVideoCaption_81062_Content_12 = {
    Text = "Посмотрев вверх… перед вами возникла лесная хижина"
  },
  AvgVideoCaption_81062_Content_13 = {
    Text = "Теперь, пожалуйста, ступайте на скрипучую лестницу"
  },
  AvgVideoCaption_81062_Content_14 = {
    Text = "Открыть знакомую деревянную Ворота"
  },
  AvgVideoCaption_81062_Content_15 = {
    Text = "Слушай, как потрескивает камин"
  },
  AvgVideoCaption_81062_Content_16 = {
    Text = "Персидский ковер"
  },
  AvgVideoCaption_81062_Content_17 = {
    Text = "Темно-красный бархатный диван, почти черный"
  },
  AvgVideoCaption_81062_Content_18 = {
    Text = "Перевернутый бокал и разлитое Прекрасное Прекрасное вино"
  },
  AvgVideoCaption_81062_Content_19 = {
    Text = "Как в вашей памяти"
  },
  AvgVideoCaption_81062_Content_2 = {
    Text = "Пожалуйста, сядь на диван напротив"
  },
  AvgVideoCaption_81062_Content_20 = {
    Text = "Вспомни ещё раз"
  },
  AvgVideoCaption_81062_Content_21 = {
    Text = "На том диване разве действительно ничего нет?"
  },
  AvgVideoCaption_81062_Content_22 = {
    Text = "Кто же окрасил персидский ковер в красный, неужели это был красное Прекрасное Прекрасное вино перед ужином?"
  },
  AvgVideoCaption_81062_Content_23 = {
    Text = "Шшш... Не торопитесь, и не нужно пытаться убежать"
  },
  AvgVideoCaption_81062_Content_24 = {
    Text = "Ваши конечности уже слабы и не могут двигаться"
  },
  AvgVideoCaption_81062_Content_25 = {
    Text = "Со всей душой, слушай меня... хорошенько почувствуй"
  },
  AvgVideoCaption_81062_Content_26 = {
    Text = "Не начинает ли чесаться третий сустав позвоночника?"
  },
  AvgVideoCaption_81062_Content_27 = {
    Text = "Похоже, твоя память уже пробудилась"
  },
  AvgVideoCaption_81062_Content_28 = {
    Text = "Это разлагающееся тело, лежащее на диване"
  },
  AvgVideoCaption_81062_Content_29 = {
    Text = "Разве это не ваш заботливый и уважаемый отец?"
  },
  AvgVideoCaption_81062_Content_3 = {
    Text = "Комфортная ли температура у камина?"
  },
  AvgVideoCaption_81062_Content_30 = {
    Text = "Неужели вы забыли? Вы, возможно, забыли?"
  },
  AvgVideoCaption_81062_Content_31 = {
    Text = "Нет, ты вовсе не забыл..."
  },
  AvgVideoCaption_81062_Content_32 = {
    Text = "Просто, ты здесь с секретной шкатулкой"
  },
  AvgVideoCaption_81062_Content_33 = {
    Text = "Я запечатал это"
  },
  AvgVideoCaption_81062_Content_34 = {
    Text = "Этот верный разум на протяжении двадцати семи лет"
  },
  AvgVideoCaption_81062_Content_35 = {
    Text = "Не позволив никому рассмотреть твое истинное лицо"
  },
  AvgVideoCaption_81062_Content_36 = {
    Text = "Это действительно заслуживает похвалы"
  },
  AvgVideoCaption_81062_Content_37 = {
    Text = "Что же сдерживает вас?"
  },
  AvgVideoCaption_81062_Content_38 = {
    Text = "Признайся в своих внутренних криках"
  },
  AvgVideoCaption_81062_Content_39 = {
    Text = "Признайся в своих желаниях и потребностях"
  },
  AvgVideoCaption_81062_Content_4 = {
    Text = "Эти часы и красный бархатный диван вызывают у тебя чувство знакомости?"
  },
  AvgVideoCaption_81062_Content_40 = {
    Text = "«Мы» примем все твои недостатки..."
  },
  AvgVideoCaption_81062_Content_41 = {
    Text = "Мораль — это всего лишь плохая рыболовная леска, которую человечество наклало на синапсы"
  },
  AvgVideoCaption_81062_Content_42 = {
    Text = "Теперь давай нежно… вытащим… рыболовный крючок… из миндалевидного тела..."
  },
  AvgVideoCaption_81062_Content_43 = {
    Text = "Скажи мне, дорогой Близкий Близкий друг..."
  },
  AvgVideoCaption_81062_Content_44 = {
    Text = "Во имя свободы... и ради удовольствия, открывшегося с тех пор"
  },
  AvgVideoCaption_81062_Content_45 = {
    Text = "Что вы сделали?"
  },
  AvgVideoCaption_81062_Content_46 = {
    Text = "В Часть 7 лет вы потушили свечу в подвале в течение тридцати секунд"
  },
  AvgVideoCaption_81062_Content_47 = {
    Text = "Чего же ты так боишься?"
  },
  AvgVideoCaption_81062_Content_48 = {
    Text = "Это Шаги снаружи?"
  },
  AvgVideoCaption_81062_Content_49 = {
    Text = "Или это твоя ожидаемая улыбка, которая вот-вот расцветет?"
  },
  AvgVideoCaption_81062_Content_5 = {
    Text = "Конечно, успокоить пациента - наша цель"
  },
  AvgVideoCaption_81062_Content_50 = {
    Text = "Тот случай утопления, который вы назвали \"неожиданным\"......"
  },
  AvgVideoCaption_81062_Content_51 = {
    Text = "В последней борьбе утопленника"
  },
  AvgVideoCaption_81062_Content_52 = {
    Text = "В отражении уголков ваших уст, напевающих"
  },
  AvgVideoCaption_81062_Content_53 = {
    Text = "Не борись, оставайся спокойным..."
  },
  AvgVideoCaption_81062_Content_54 = {
    Text = "Вы не хотите знать, куда ушел предыдущий борющийся господин"
  },
  AvgVideoCaption_81062_Content_55 = {
    Text = "Но розы в заднем дворе церкви в этом году цветут особенно ярко, не так ли?"
  },
  AvgVideoCaption_81062_Content_56 = {
    Text = "Хороший ребёнок"
  },
  AvgVideoCaption_81062_Content_57 = {
    Text = "Теперь, положите свою руку в мою"
  },
  AvgVideoCaption_81062_Content_58 = {
    Text = "Да, положи это на ладонь..."
  },
  AvgVideoCaption_81062_Content_59 = {
    Text = "Посмотри внимательно"
  },
  AvgVideoCaption_81062_Content_6 = {
    Text = "Теперь, пожалуйста, пройдите через маятник и смотрите в мои глаза"
  },
  AvgVideoCaption_81062_Content_60 = {
    Text = "Можно ли это вообще назвать рукой?"
  },
  AvgVideoCaption_81062_Content_61 = {
    Text = "Хитин растет"
  },
  AvgVideoCaption_81062_Content_62 = {
    Text = "Оболочка покроет слабое, изящное, беспомощное тело..."
  },
  AvgVideoCaption_81062_Content_63 = {
    Text = "Не стоит пытаться кричать"
  },
  AvgVideoCaption_81062_Content_64 = {
    Text = "Пожалуйста, бережно относись к своим голосовым связкам"
  },
  AvgVideoCaption_81062_Content_65 = {
    Text = "Он ещё не полностью преобразился..."
  },
  AvgVideoCaption_81062_Content_66 = {
    Text = "Моральные кандалы, которые люди используют для заключения себя"
  },
  AvgVideoCaption_81062_Content_67 = {
    Text = "Неужели они не отвалятся один за другим?"
  },
  AvgVideoCaption_81062_Content_68 = {
    Text = "Как змея, сбрасывающая старую ненужную шкуру..."
  },
  AvgVideoCaption_81062_Content_69 = {
    Text = "Я освобожу тебя…"
  },
  AvgVideoCaption_81062_Content_7 = {
    Text = "Глубокий вдох"
  },
  AvgVideoCaption_81062_Content_70 = {
    Text = "Да... именно так радужная оболочка делится на идеальную шестиугольную матрицу"
  },
  AvgVideoCaption_81062_Content_71 = {
    Text = "Давайте восхвалим этот древний сосуд, который вскоре пробудится…"
  },
  AvgVideoCaption_81062_Content_72 = {
    Text = "Чтобы окончательно попрощаться с развратным прошлым"
  },
  AvgVideoCaption_81062_Content_73 = {
    Text = "Давайте погрузим социальные маски в концентрированную серную кислоту…"
  },
  AvgVideoCaption_81062_Content_74 = {
    Text = "Вместе с твоим смешным банковским счетом и дипломами"
  },
  AvgVideoCaption_81062_Content_75 = {
    Text = "Смотри, как они разлагаются и растворяются, как гнезда червей"
  },
  AvgVideoCaption_81062_Content_76 = {
    Text = "Отлично, отлично……"
  },
  AvgVideoCaption_81062_Content_77 = {
    Text = "Глубокий вдох..."
  },
  AvgVideoCaption_81062_Content_78 = {
    Text = "Теперь, пожалуйста, следуйте за мной"
  },
  AvgVideoCaption_81062_Content_79 = {
    Text = "Я добровольно отказываюсь от низкосортной генетической цепи разумного человека"
  },
  AvgVideoCaption_81062_Content_8 = {
    Text = "Тепло камина медленно поднимается к вашему щиколотке"
  },
  AvgVideoCaption_81062_Content_80 = {
    Text = "Подключите нейронные соединения к облаку улья"
  },
  AvgVideoCaption_81062_Content_81 = {
    Text = "Человечность — это всего лишь смешная мимикрия"
  },
  AvgVideoCaption_81062_Content_82 = {
    Text = "Как Глава о бабочке, временно замаскировавшаяся под листья"
  },
  AvgVideoCaption_81062_Content_83 = {
    Text = "Теперь пришло время вернуться в вечный материнский лоно гнезда"
  },
  AvgVideoCaption_81062_Content_84 = {
    Text = "Наверняка вы уже не слышите звука сердцебиения, верно?"
  },
  AvgVideoCaption_81062_Content_85 = {
    Text = "Частота крыльев роя уже заменена на жалкие толчки…"
  },
  AvgVideoCaption_81062_Content_86 = {
    Text = "Прощай со старым телом, которое сгорает в угле"
  },
  AvgVideoCaption_81062_Content_87 = {
    Text = "Вы, с юридической точки зрения, «мертвы»"
  },
  AvgVideoCaption_81062_Content_88 = {
    Text = "Ты получишь первую порцию оплодотворяющих мешочков через десять минут"
  },
  AvgVideoCaption_81062_Content_89 = {
    Text = "Закрой глаза"
  },
  AvgVideoCaption_81062_Content_9 = {
    Text = "Теперь представьте, что вы прогуливаетесь по тропинкам Гайд-парка"
  },
  AvgVideoCaption_81062_Content_90 = {
    Text = "Принять существующую тьму……"
  },
  AvgVideoCaption_81062_Content_91 = {
    Text = "Затем снова откройте свои настоящие глаза…"
  },
  AvgVideoCaption_81062_Content_92 = {
    Text = "Поздравляю…… Вы сейчас ближе к Богу, чем любой человек"
  },
  AvgVideoCaption_81062_Content_93 = {
    Text = "Истина вселенной, увиденная через трёхсотшестидесятиградусные глаза..."
  },
  AvgVideoCaption_81062_Content_94 = {
    Text = "Добро пожаловать, чтобы послушать Резонанс миллиардов сердец в глубинах земли..."
  },
  AvgVideoCaption_81062_Content_95 = {
    Text = "Добро пожаловать, чтобы стать совершенным инструментом для Него..."
  },
  AvgVideoCaption_81062_Content_96 = {
    Text = "Добро пожаловать домой"
  },
  AvgVideoCaption_81283_Content_1 = {
    Text = "Я разделяю твою боль"
  },
  AvgVideoCaption_81283_Content_10 = {
    Text = "Позвольте мне дотронуться до вашей души"
  },
  AvgVideoCaption_81283_Content_11 = {
    Text = "Касаясь всех глубоко скрытых в вашем сердце страданий и желаний"
  },
  AvgVideoCaption_81283_Content_12 = {
    Text = "Ах, именно так..."
  },
  AvgVideoCaption_81283_Content_13 = {
    Text = "Эта психологическая консультация, наконец, дошла до моего любимого этапа"
  },
  AvgVideoCaption_81283_Content_14 = {
    Text = "Грусть, Страх, беспомощность"
  },
  AvgVideoCaption_81283_Content_15 = {
    Text = "Нейромедиатор признался мне в вашей истине"
  },
  AvgVideoCaption_81283_Content_16 = {
    Text = "Но еще недостаточно, далеко недостаточно"
  },
  AvgVideoCaption_81283_Content_17 = {
    Text = "Покажите мне больше!"
  },
  AvgVideoCaption_81283_Content_18 = {
    Text = "Слой за слоем снимаете завесу с вашего сердца и души"
  },
  AvgVideoCaption_81283_Content_19 = {
    Text = "Покажи мне своё самое глубокое отчаяние, борьбу"
  },
  AvgVideoCaption_81283_Content_2 = {
    Text = "Полное понимание чувств"
  },
  AvgVideoCaption_81283_Content_20 = {
    Text = "Чтобы я мог вкусить…"
  },
  AvgVideoCaption_81283_Content_21 = {
    Text = "Ах, извините"
  },
  AvgVideoCaption_81283_Content_22 = {
    Text = "Увлёкшись беседой с высокопоставленным пациентом"
  },
  AvgVideoCaption_81283_Content_23 = {
    Text = "Ждал долго, пожалуйста, входите"
  },
  AvgVideoCaption_81283_Content_24 = {
    Text = "Давайте вместе начнем путешествие по душе"
  },
  AvgVideoCaption_81283_Content_3 = {
    Text = "Я понимаю ваше желание возродиться"
  },
  AvgVideoCaption_81283_Content_4 = {
    Text = "Не волнуйся, оставь всё мне"
  },
  AvgVideoCaption_81283_Content_5 = {
    Text = "Я сделаю так, чтобы ты выздоровел"
  },
  AvgVideoCaption_81283_Content_6 = {
    Text = "Найди своего настоящего себя"
  },
  AvgVideoCaption_81283_Content_7 = {
    Text = "Сейчас, расслабьтесь..."
  },
  AvgVideoCaption_81283_Content_8 = {
    Text = "Покажи мне своё внутреннее я"
  },
  AvgVideoCaption_81283_Content_9 = {
    Text = "Освободи своё подсознание и духовность для меня"
  },
  AvgVideoCaption_84327_Content_1 = {
    Text = "Корабль тонет! Быстро откройте Ворота!"
  },
  AvgVideoCaption_84327_Content_10 = {
    Text = "Он единственный «пассажир» на борту Нодильи в этот момент"
  },
  AvgVideoCaption_84327_Content_100 = {
    Text = "Но сейчас я больше не человек"
  },
  AvgVideoCaption_84327_Content_101 = {
    Text = "Поэтому те, кто Призывал нас"
  },
  AvgVideoCaption_84327_Content_102 = {
    Text = "Он указывал мне, обещал мне"
  },
  AvgVideoCaption_84327_Content_103 = {
    Text = "Затонувшее царство рассказывает о своём прошлом в водах глубокого моря"
  },
  AvgVideoCaption_84327_Content_104 = {
    Text = "А расколотая статуя из слоновой кости также показала мне истинного бога"
  },
  AvgVideoCaption_84327_Content_105 = {
    Text = "Сейчас реальность и Иллюзия уже не важны"
  },
  AvgVideoCaption_84327_Content_106 = {
    Text = "Для богов всё есть Иллюзия; всё не имеет смысла"
  },
  AvgVideoCaption_84327_Content_107 = {
    Text = "Морская вода все еще обнимает меня, окутывает меня, поглощает меня"
  },
  AvgVideoCaption_84327_Content_108 = {
    Text = "А за этими воротами бесконечные измерения и пустота"
  },
  AvgVideoCaption_84327_Content_109 = {
    Text = "Мой поверхностный ум уже полностью пропитался глубоким морем"
  },
  AvgVideoCaption_84327_Content_11 = {
    Text = "Да, это ты спас меня?"
  },
  AvgVideoCaption_84327_Content_110 = {
    Text = "Невозможно больше думать ни на миг"
  },
  AvgVideoCaption_84327_Content_111 = {
    Text = "А мое тело поддалось этому океану"
  },
  AvgVideoCaption_84327_Content_112 = {
    Text = "Тот бесконечный мир и бездны пустоты"
  },
  AvgVideoCaption_84327_Content_113 = {
    Text = "Это будет мой новый курс"
  },
  AvgVideoCaption_84327_Content_12 = {
    Text = "Добро пожаловать на борт Нептуна"
  },
  AvgVideoCaption_84327_Content_13 = {
    Text = "Я штурман этого корабля, Коперсант"
  },
  AvgVideoCaption_84327_Content_14 = {
    Text = "Пожалуйста, заботьтесь о корабле и соблюдайте порядок"
  },
  AvgVideoCaption_84327_Content_15 = {
    Text = "И помните код спасательной шлюпки, обычно он напечатан на обратной стороне вашего ключа от номера"
  },
  AvgVideoCaption_84327_Content_16 = {
    Text = "Но по правилам пиратам нельзя получать ключи от комнат"
  },
  AvgVideoCaption_84327_Content_17 = {
    Text = "Очень сожалею"
  },
  AvgVideoCaption_84327_Content_18 = {
    Text = "Ха? Это вообще не вопрос карточки!"
  },
  AvgVideoCaption_84327_Content_19 = {
    Text = "Здесь, здесь — глубокое море"
  },
  AvgVideoCaption_84327_Content_2 = {
    Text = "Спаси... меня... спаси меня..."
  },
  AvgVideoCaption_84327_Content_20 = {
    Text = "Я дышу в море! Живой!"
  },
  AvgVideoCaption_84327_Content_21 = {
    Text = "Ах, я определенно сошел с ума"
  },
  AvgVideoCaption_84327_Content_22 = {
    Text = "Как они и сказали, с момента получения этого странного слонового головы я сошел с ума"
  },
  AvgVideoCaption_84327_Content_23 = {
    Text = "Что за резные слоновые головы, что за Лемурия, все это фантомы, все это мечты!"
  },
  AvgVideoCaption_84327_Content_24 = {
    Text = "Когда я проснусь, я вернусь домой"
  },
  AvgVideoCaption_84327_Content_25 = {
    Text = "Да, домой, домой…"
  },
  AvgVideoCaption_84327_Content_26 = {
    Text = "Думаю, теперь вы должны понять свое положение"
  },
  AvgVideoCaption_84327_Content_27 = {
    Text = "Здесь затонувший корабль Нодириуса, здесь также глубокое море"
  },
  AvgVideoCaption_84327_Content_28 = {
    Text = "Скоро мы будем тонуть на дне моря"
  },
  AvgVideoCaption_84327_Content_29 = {
    Text = "Я постараюсь продлить вашу жизнь"
  },
  AvgVideoCaption_84327_Content_3 = {
    Text = "Тот день был 12 сентября"
  },
  AvgVideoCaption_84327_Content_30 = {
    Text = "Но как штурман и единственный Член экипажа"
  },
  AvgVideoCaption_84327_Content_31 = {
    Text = "Я обязан признать перед пассажирами, что мои возможности ограничены"
  },
  AvgVideoCaption_84327_Content_32 = {
    Text = "После того дня, пираты погрузились в молчание"
  },
  AvgVideoCaption_84327_Content_33 = {
    Text = "Он больше не пытается сбежать, а стоит у окна, заполненного водой, в каюте"
  },
  AvgVideoCaption_84327_Content_34 = {
    Text = "Смотрящая в глубину через иллюминатор, шепчет"
  },
  AvgVideoCaption_84327_Content_35 = {
    Text = "Иногда он смеется во весь голос"
  },
  AvgVideoCaption_84327_Content_36 = {
    Text = "Иногда безумие"
  },
  AvgVideoCaption_84327_Content_37 = {
    Text = "Иногда зовущая Лемурия"
  },
  AvgVideoCaption_84327_Content_38 = {
    Text = "Лемурия зовет меня"
  },
  AvgVideoCaption_84327_Content_39 = {
    Text = "Иногда кричит «мама», «домой»"
  },
  AvgVideoCaption_84327_Content_4 = {
    Text = "Корабль Нодириус стал призрачным судном в 791-й день"
  },
  AvgVideoCaption_84327_Content_40 = {
    Text = "Лемурия, домой..."
  },
  AvgVideoCaption_84327_Content_41 = {
    Text = "Я хочу вернуться в Лемурию..."
  },
  AvgVideoCaption_84327_Content_42 = {
    Text = "Я плавал по многим местам, но никогда не слышал о «Лемурии»"
  },
  AvgVideoCaption_84327_Content_43 = {
    Text = "Боюсь, единственный пассажир «Нордиера»"
  },
  AvgVideoCaption_84327_Content_44 = {
    Text = "Уже страдаю от морской близорукости"
  },
  AvgVideoCaption_84327_Content_45 = {
    Text = "Это распространённое заболевание в мореплавании"
  },
  AvgVideoCaption_84327_Content_46 = {
    Text = "Согласно описанию врача на борту Ральфа"
  },
  AvgVideoCaption_84327_Content_47 = {
    Text = "Это поверхностный человеческий мозг"
  },
  AvgVideoCaption_84327_Content_48 = {
    Text = "Невозможно полностью понять симптомы, вызванные глубоким морем"
  },
  AvgVideoCaption_84327_Content_49 = {
    Text = "Сейчас мы не плывём по морю"
  },
  AvgVideoCaption_84327_Content_5 = {
    Text = "Пираты, отвергнутые товарищами, провалили Побег"
  },
  AvgVideoCaption_84327_Content_50 = {
    Text = "А я нахожусь в море, и, вместе с Нордлиусом, постоянно погружаюсь в глубокие воды"
  },
  AvgVideoCaption_84327_Content_51 = {
    Text = "Эта ситуация способна свести с ума любого"
  },
  AvgVideoCaption_84327_Content_52 = {
    Text = "Даже я..."
  },
  AvgVideoCaption_84327_Content_53 = {
    Text = "Уже мертв, и сознание по какой-то причине прикреплено к «Нордиера»"
  },
  AvgVideoCaption_84327_Content_54 = {
    Text = "Спасая юного пирата, я тоже увидел галлюцинацию"
  },
  AvgVideoCaption_84327_Content_55 = {
    Text = "Я увидел, как возвращается «Нодериус»..."
  },
  AvgVideoCaption_84327_Content_56 = {
    Text = "Я также видел, как «Нордиера» тонет..."
  },
  AvgVideoCaption_84327_Content_57 = {
    Text = "Сначала я всё ещё сохранял рассудок"
  },
  AvgVideoCaption_84327_Content_58 = {
    Text = "Отличить, что является иллюзией, а что - реальностью"
  },
  AvgVideoCaption_84327_Content_59 = {
    Text = "Но потом…"
  },
  AvgVideoCaption_84327_Content_6 = {
    Text = "Когда \"Наутилус\" погружается в море"
  },
  AvgVideoCaption_84327_Content_60 = {
    Text = "Я слышал, я слышал"
  },
  AvgVideoCaption_84327_Content_61 = {
    Text = "Он нас призывает!"
  },
  AvgVideoCaption_84327_Content_62 = {
    Text = "Всякий, кто потеряется, мой Господь укажет путь"
  },
  AvgVideoCaption_84327_Content_63 = {
    Text = "Всякий, кто пожелает, мой Господь обещает"
  },
  AvgVideoCaption_84327_Content_64 = {
    Text = "Да-да, направь меня, пообещай мне!"
  },
  AvgVideoCaption_84327_Content_65 = {
    Text = "Великий Господь, веди меня в Лемурию, позволь мне войти в ваше царство бога!"
  },
  AvgVideoCaption_84327_Content_66 = {
    Text = "Царство бога, в Царстве бога я обрету счастье, обрету бессмертие"
  },
  AvgVideoCaption_84327_Content_67 = {
    Text = "Мы пойдем домой! Домой! Домой!"
  },
  AvgVideoCaption_84327_Content_68 = {
    Text = "Ральф не ошибся"
  },
  AvgVideoCaption_84327_Content_69 = {
    Text = "Поверхностный человеческий разум не может полностью понять глубочайший Океан"
  },
  AvgVideoCaption_84327_Content_7 = {
    Text = "На самом деле, я ненавижу пиратов"
  },
  AvgVideoCaption_84327_Content_70 = {
    Text = "Поэтому, когда тот величественный город появился передо мной"
  },
  AvgVideoCaption_84327_Content_71 = {
    Text = "Я воспринимаю это как галлюцинацию, вызванную морской безумием"
  },
  AvgVideoCaption_84327_Content_72 = {
    Text = "Это был город, который нельзя описать словами, нельзя назвать"
  },
  AvgVideoCaption_84327_Content_73 = {
    Text = "Сияющий древним светом, он хаотично разбросан на морском дне"
  },
  AvgVideoCaption_84327_Content_74 = {
    Text = "В этой бездонной глубине моря, тихо спит, стоит"
  },
  AvgVideoCaption_84327_Content_75 = {
    Text = "Непринужденное ожидание"
  },
  AvgVideoCaption_84327_Content_76 = {
    Text = "Мы, Гость, попали в сети"
  },
  AvgVideoCaption_84327_Content_77 = {
    Text = "Лемурия!"
  },
  AvgVideoCaption_84327_Content_78 = {
    Text = "Это Лемурия!"
  },
  AvgVideoCaption_84327_Content_79 = {
    Text = "Он нас призывает, он нас призывает!"
  },
  AvgVideoCaption_84327_Content_8 = {
    Text = "Ненависть ко всем, кто мешает безопасному плаванию судна"
  },
  AvgVideoCaption_84327_Content_80 = {
    Text = "Опасно, не подходите!"
  },
  AvgVideoCaption_84327_Content_81 = {
    Text = "Таким образом, единственный пассажир «Нордиера» умер на моих глазах"
  },
  AvgVideoCaption_84327_Content_82 = {
    Text = "Осталась только эта странная резьба по слоновой кости"
  },
  AvgVideoCaption_84327_Content_83 = {
    Text = "Я знаю, каков должен быть наиболее разумный выбор в этот момент"
  },
  AvgVideoCaption_84327_Content_84 = {Text = "Но.."},
  AvgVideoCaption_84327_Content_85 = {
    Text = "Я - штурман, знать море - моя необходимая работа"
  },
  AvgVideoCaption_84327_Content_86 = {
    Text = "Когда Карта сознания дает Разгром"
  },
  AvgVideoCaption_84327_Content_87 = {
    Text = "То, что мне нужно сделать, не избегать, а исправлять"
  },
  AvgVideoCaption_84327_Content_88 = {
    Text = "<Red:Так что, приближи это>"
  },
  AvgVideoCaption_84327_Content_89 = {
    Text = "А для исправления ошибок нужно..."
  },
  AvgVideoCaption_84327_Content_9 = {Text = "Но.."},
  AvgVideoCaption_84327_Content_90 = {
    Text = "Требуется глубокое понимание проблемы, ощущение проблемы"
  },
  AvgVideoCaption_84327_Content_91 = {
    Text = "Исследовать эту землю, где спят боги"
  },
  AvgVideoCaption_84327_Content_92 = {
    Text = "<Red:Так что, ответь на это>"
  },
  AvgVideoCaption_84327_Content_93 = {
    Text = "Морские пути, которые не могут привести к счастью в мир людей"
  },
  AvgVideoCaption_84327_Content_94 = {
    Text = "Только принесшие все жертвы достойны взгляда на Царство бога"
  },
  AvgVideoCaption_84327_Content_95 = {
    Text = "<Red:Так что, обратись к этому！>"
  },
  AvgVideoCaption_84327_Content_96 = {
    Text = "<Red:Пожертвуй всем！>"
  },
  AvgVideoCaption_84327_Content_97 = {
    Text = "Наконец, после того как я пожертвовал всем, я увидел..."
  },
  AvgVideoCaption_84327_Content_98 = {
    Text = "Тот огромный, возвышенный, безкрайний и неописуемый существование……"
  },
  AvgVideoCaption_84327_Content_99 = {
    Text = "Поверхностный человеческий разум не может полностью понять глубочайший Океан"
  },
  AvgVideoCaption_90244_Content_1 = {Text = "Ха..."},
  AvgVideoCaption_90244_Content_10 = {
    Text = "Как глубоко застряло... Перья слиплись от крови"
  },
  AvgVideoCaption_90244_Content_100 = {
    Text = "Так много мест из рукописи, которые мы еще не посетили; очень хочу увидеть их все"
  },
  AvgVideoCaption_90244_Content_101 = {
    Text = "Я обязательно пойду"
  },
  AvgVideoCaption_90244_Content_102 = {
    Text = "Наконец, рыцарь возвратил принцессу в страну"
  },
  AvgVideoCaption_90244_Content_103 = {
    Text = "Бесчисленные цветы были розданы на улицах, приветствующих их"
  },
  AvgVideoCaption_90244_Content_104 = {
    Text = "Имя рыцаря стало знаменито в королевстве"
  },
  AvgVideoCaption_90244_Content_105 = {
    Text = "Ах, это закончилось"
  },
  AvgVideoCaption_90244_Content_106 = {
    Text = "Каждый раз так интересно знать, что произойдет после окончания истории?"
  },
  AvgVideoCaption_90244_Content_107 = {
    Text = "Брат, что ты думаешь, что случилось с рыцарем потом?"
  },
  AvgVideoCaption_90244_Content_108 = {
    Text = "Получит ли он славу, богатство и любовь принцессы?"
  },
  AvgVideoCaption_90244_Content_109 = {
    Text = "Я не знаю..."
  },
  AvgVideoCaption_90244_Content_11 = {
    Text = "Я сначала уберу эти грязные вещи"
  },
  AvgVideoCaption_90244_Content_110 = {
    Text = "Но хотя бы он уже обрёл славу"
  },
  AvgVideoCaption_90244_Content_111 = {
    Text = "Итак, он вернул принцессу из далекого путешествия"
  },
  AvgVideoCaption_90244_Content_112 = {
    Text = "Король, наверное, вознаградит его, да?"
  },
  AvgVideoCaption_90244_Content_113 = {
    Text = "Верно, король, должно быть, не мелочный человек"
  },
  AvgVideoCaption_90244_Content_114 = {
    Text = "Он сбежал с принцессой из замка и прошёл ещё так много мест"
  },
  AvgVideoCaption_90244_Content_115 = {
    Text = "А может, принцесса тоже полюбит его?"
  },
  AvgVideoCaption_90244_Content_116 = {
    Text = "Угу... это имеет смысл"
  },
  AvgVideoCaption_90244_Content_117 = {
    Text = "Хотя рыцарь сказал, что ничего не хочет"
  },
  AvgVideoCaption_90244_Content_118 = {
    Text = "Но всё-таки он получит всё"
  },
  AvgVideoCaption_90244_Content_119 = {
    Text = "Очевидно, что смелые люди в конце концов... получат... все..."
  },
  AvgVideoCaption_90244_Content_12 = {
    Text = "...болит, да? Прости, давай полегче"
  },
  AvgVideoCaption_90244_Content_120 = {
    Text = "(Уснуть... эти дни бегства действительно изнурительны)"
  },
  AvgVideoCaption_90244_Content_121 = {
    Text = "(Столько перьев выпало, жаль... м? это все еще целое)"
  },
  AvgVideoCaption_90244_Content_122 = {
    Text = "(Соберу сначала, когда будет время, сделаю Поллуксу ожерелье)"
  },
  AvgVideoCaption_90244_Content_123 = {
    Text = "(Какой круглый месяц, какое красивое звездное небо)"
  },
  AvgVideoCaption_90244_Content_124 = {
    Text = "(Как и в книге... храбрый человек получит все?)"
  },
  AvgVideoCaption_90244_Content_125 = {
    Text = "(История в книге не обманет, верно?)"
  },
  AvgVideoCaption_90244_Content_126 = {
    Text = "(Спокойной ночи, рыцарь Поллукса)"
  },
  AvgVideoCaption_90244_Content_13 = {
    Text = "Ну, всё не так уж плохо"
  },
  AvgVideoCaption_90244_Content_14 = {
    Text = "По сравнению с чувством, когда на ритуале модификации вскрыли грудь и на внутренностях вырезали заклинания"
  },
  AvgVideoCaption_90244_Content_15 = {
    Text = "Эта боль ничто"
  },
  AvgVideoCaption_90244_Content_16 = {
    Text = "...да, это так, из всех нас ты несешь больше всего боли"
  },
  AvgVideoCaption_90244_Content_17 = {
    Text = "(Ах, черт, не то сказал...)"
  },
  AvgVideoCaption_90244_Content_18 = {
    Text = "Все прошло, брат"
  },
  AvgVideoCaption_90244_Content_19 = {
    Text = "Раньше мы не могли ничего решать, но отныне мы будем свободны!"
  },
  AvgVideoCaption_90244_Content_2 = {
    Text = "Должно быть, это чудовище больше не будет нас преследовать"
  },
  AvgVideoCaption_90244_Content_20 = {
    Text = "Прочитай мне еще раз историю из рукописи"
  },
  AvgVideoCaption_90244_Content_21 = {
    Text = "Как и после каждого обряда превращения, когда слушаешь истории, боль от ран утихает"
  },
  AvgVideoCaption_90244_Content_22 = {
    Text = "Хорошо"
  },
  AvgVideoCaption_90244_Content_23 = {
    Text = "Итак, давайте расскажем еще раз, приключенческую историю легендарного рыцаря"
  },
  AvgVideoCaption_90244_Content_24 = {
    Text = "Наконец, рыцарь, прибывший в замок, нашел монстра в тени"
  },
  AvgVideoCaption_90244_Content_25 = {
    Text = "Спрашивая это о местонахождении принцессы"
  },
  AvgVideoCaption_90244_Content_26 = {
    Text = "То темно зеленое чудовище было огромным, как великан"
  },
  AvgVideoCaption_90244_Content_27 = {
    Text = "Странные и ужасные звуки доносятся из глубин дрожащего тела"
  },
  AvgVideoCaption_90244_Content_28 = {
    Text = "Она высоко подняла топор"
  },
  AvgVideoCaption_90244_Content_29 = {
    Text = "Холодный Погоня за светом, как новый месяц, разрезал тишину в зале"
  },
  AvgVideoCaption_90244_Content_3 = {
    Text = "Отдохни, ах..."
  },
  AvgVideoCaption_90244_Content_30 = {
    Text = "Храбрый рыцарь стоит спокойно"
  },
  AvgVideoCaption_90244_Content_31 = {
    Text = "Его золотые волосы слегка колыхались на ветру"
  },
  AvgVideoCaption_90244_Content_32 = {
    Text = "Топор со свистом опускался, но замер перед шеей рыцаря"
  },
  AvgVideoCaption_90244_Content_33 = {
    Text = "«Это дар за вашу верность обещанию.»"
  },
  AvgVideoCaption_90244_Content_34 = {
    Text = "Монстр, скалясь, прошептал, его жужжащий голос напоминал звук ржавых железок, трущихся Близкий Близкий друг о друга"
  },
  AvgVideoCaption_90244_Content_35 = {
    Text = "«Ты не уступил в сегодняшнем поединке, и достоин имени рыцаря.»"
  },
  AvgVideoCaption_90244_Content_36 = {
    Text = "Как будто сегодняшние монстры нас не победили!"
  },
  AvgVideoCaption_90244_Content_37 = {
    Text = "Вторая атака снова опустилась"
  },
  AvgVideoCaption_90244_Content_38 = {
    Text = "Останавливаясь совсем близко, лишь немного оцарапав кожу рыцаря..."
  },
  AvgVideoCaption_90244_Content_39 = {
    Text = "Поллукс, даже самые главные перья сломаны"
  },
  AvgVideoCaption_90244_Content_4 = {
    Text = "Поллукс! Твои крылья сильно повреждены"
  },
  AvgVideoCaption_90244_Content_40 = {
    Text = "Ты всегда так заботился о них..."
  },
  AvgVideoCaption_90244_Content_41 = {
    Text = "Не беспокойтесь, перья снова отрастут, это символ свободы"
  },
  AvgVideoCaption_90244_Content_42 = {
    Text = "Как Реальность рыцарь, не так ли?"
  },
  AvgVideoCaption_90244_Content_43 = {
    Text = "Угу... рана вокруг вычищена"
  },
  AvgVideoCaption_90244_Content_44 = {
    Text = "Твоё перо распущено, я помогу почистить его"
  },
  AvgVideoCaption_90244_Content_45 = {
    Text = "Заботитесь, сэр рыцарь Кастор"
  },
  AvgVideoCaption_90244_Content_46 = {
    Text = "Пожалуйста, продолжайте рассказывать историю приключений!"
  },
  AvgVideoCaption_90244_Content_47 = {
    Text = "Хорошо, я понял"
  },
  AvgVideoCaption_90244_Content_48 = {
    Text = "В глазах монстра блестела искренняя благодарность"
  },
  AvgVideoCaption_90244_Content_49 = {
    Text = "«Это наказание за то, что вы спасли моё дитя, но украли у неё Ключ и проникли в замок.»"
  },
  AvgVideoCaption_90244_Content_5 = {
    Text = "Черт возьми, только сейчас я не смог его задержать, если бы я..."
  },
  AvgVideoCaption_90244_Content_50 = {
    Text = "Рыцарь внезапно просветлел"
  },
  AvgVideoCaption_90244_Content_51 = {
    Text = "«Та утонувшая девушка – это ваше дитя!»"
  },
  AvgVideoCaption_90244_Content_52 = {
    Text = "Монстр кивнул головой"
  },
  AvgVideoCaption_90244_Content_53 = {
    Text = "«Да, и следующий последний Удар – это будет наш истинный бой.»"
  },
  AvgVideoCaption_90244_Content_54 = {
    Text = "Рыцарь поднял меч, с кончиком вверх, обращаясь к монстру"
  },
  AvgVideoCaption_90244_Content_55 = {
    Text = "Однако в этот момент образ монстра вдруг исчез"
  },
  AvgVideoCaption_90244_Content_56 = {
    Text = "Рыцарь осторожно продвигался вперед"
  },
  AvgVideoCaption_90244_Content_57 = {
    Text = "Пустой замок окутан искривленной тенью"
  },
  AvgVideoCaption_90244_Content_58 = {
    Text = "Только иллюзорные звуки чудовища сливались в его ушах"
  },
  AvgVideoCaption_90244_Content_59 = {
    Text = "「Доблестный рыцарь, почему вы продолжаете бороться?」"
  },
  AvgVideoCaption_90244_Content_6 = {
    Text = "Ладно, не говори так, мы же только впервые выходим наружу"
  },
  AvgVideoCaption_90244_Content_60 = {
    Text = "«Это ради чести и восхваления?»"
  },
  AvgVideoCaption_90244_Content_61 = {
    Text = "Группа людей неожиданно появляется, они один за другим окружают рыцаря"
  },
  AvgVideoCaption_90244_Content_62 = {
    Text = "На многих лицах сияет улыбка, непрерывно воспевая его славу"
  },
  AvgVideoCaption_90244_Content_63 = {
    Text = "Рыцарь заметил странности в этих фантомах"
  },
  AvgVideoCaption_90244_Content_64 = {
    Text = "Его выражение было непоколебимо, мгновенно разрывая эти ложные тени"
  },
  AvgVideoCaption_90244_Content_65 = {
    Text = "«Так это ради наград и богатств?»"
  },
  AvgVideoCaption_90244_Content_66 = {
    Text = "Покорный Сквайр предстал перед рыцарем"
  },
  AvgVideoCaption_90244_Content_67 = {
    Text = "Он держал сверкающие золотые монеты и великолепную корону, украшенную кроваво-красными рубинами"
  },
  AvgVideoCaption_90244_Content_68 = {
    Text = "Подобострастно подарено рыцарю"
  },
  AvgVideoCaption_90244_Content_69 = {
    Text = "Рыцарь не посмотрел на корону, символизирующую бесконечное богатство и Независимый"
  },
  AvgVideoCaption_90244_Content_7 = {
    Text = "И не говори, разве это не получалось убежать? Радуйся, мы уже очень сильные!"
  },
  AvgVideoCaption_90244_Content_70 = {
    Text = "Разрубив фантом слуги мечом"
  },
  AvgVideoCaption_90244_Content_71 = {
    Text = "Продолжая своим пронзительным голосом, монстр сказал: «О? Неужели это ради любви принцессы?»"
  },
  AvgVideoCaption_90244_Content_72 = {
    Text = "Красивый образ принцессы появляется перед рыцарем"
  },
  AvgVideoCaption_90244_Content_73 = {
    Text = "Её длинные ресницы трепетали, и она с мечтательным взглядом потянулась к рыцарю"
  },
  AvgVideoCaption_90244_Content_74 = {
    Text = "Рыцарь одним ударом разрубил фантом принцессы"
  },
  AvgVideoCaption_90244_Content_75 = {
    Text = "«Нет, это вовсе не так. Я сражаюсь только для того, чтобы спасти страждущих, чтобы другие больше не сражались!»"
  },
  AvgVideoCaption_90244_Content_76 = {
    Text = "В момент окончания речи рыцаря"
  },
  AvgVideoCaption_90244_Content_77 = {
    Text = "Те бесчисленные, как щупальца, колышущиеся тени и будто настоящие иллюзии исчезли"
  },
  AvgVideoCaption_90244_Content_78 = {
    Text = "С громким звуком рыцарь встречает мечом топор монстра, отбросив топор прочь"
  },
  AvgVideoCaption_90244_Content_79 = {
    Text = "«Ты доказал своё милосердие, верность и чистоту»"
  },
  AvgVideoCaption_90244_Content_8 = {
    Text = "...ты прав, давай я сначала обработаю твою рану"
  },
  AvgVideoCaption_90244_Content_80 = {
    Text = "«Теперь вы можете забрать принцессу.»"
  },
  AvgVideoCaption_90244_Content_81 = {
    Text = "Та ужасная привидение рассеялось, как дым"
  },
  AvgVideoCaption_90244_Content_82 = {
    Text = "На месте остались лишь старые, покрытые зелёной ржавчиной доспехи"
  },
  AvgVideoCaption_90244_Content_83 = {
    Text = "Рыцарь низко поклонился перед тем доспехом"
  },
  AvgVideoCaption_90244_Content_84 = {
    Text = "Он медленно поднимался по винтовой лестнице, Шаг за шагом"
  },
  AvgVideoCaption_90244_Content_85 = {
    Text = "Наконец, рыцарь нашел принцессу на вершине замка"
  },
  AvgVideoCaption_90244_Content_86 = {
    Text = "Принцесса, запертая в замке, как и мы раньше"
  },
  AvgVideoCaption_90244_Content_87 = {
    Text = "Но нет рыцаря, который спасёт нас..."
  },
  AvgVideoCaption_90244_Content_88 = {
    Text = "Мы сами себя спасли"
  },
  AvgVideoCaption_90244_Content_89 = {
    Text = "Мы сами себе рыцари"
  },
  AvgVideoCaption_90244_Content_9 = {Text = "Ага!"},
  AvgVideoCaption_90244_Content_90 = {
    Text = "Верно! Ха-ха-ха"
  },
  AvgVideoCaption_90244_Content_91 = {
    Text = "Если подумать, как храбрая принцесса поднимает меч"
  },
  AvgVideoCaption_90244_Content_92 = {
    Text = "Эта история вовсе не про рыцаря"
  },
  AvgVideoCaption_90244_Content_93 = {
    Text = "Да, но все же, рыцарь спас принцессу"
  },
  AvgVideoCaption_90244_Content_94 = {
    Text = "Он ведёт принцессу на коне, мчась под обширным звёздным небом и круглой луной"
  },
  AvgVideoCaption_90244_Content_95 = {
    Text = "Они переходят через широкие луга и прозрачные потоки"
  },
  AvgVideoCaption_90244_Content_96 = {
    Text = "Пересекая величественные горы и густые леса"
  },
  AvgVideoCaption_90244_Content_97 = {
    Text = "Степи, горы..."
  },
  AvgVideoCaption_90244_Content_98 = {
    Text = "Подумайте, куда мы идем?"
  },
  AvgVideoCaption_90244_Content_99 = {
    Text = "А еще море, пустыня, деревня и пастбище"
  },
  AvgVideoCaption_96010_Content_1 = {
    Text = "Добро пожаловать в мой замок, господин Пикман"
  },
  AvgVideoCaption_96010_Content_10 = {Text = "Но.."},
  AvgVideoCaption_96010_Content_100 = {
    Text = "Конечно"
  },
  AvgVideoCaption_96010_Content_101 = {
    Text = "Пожалуйста, продолжайте кушать, мистер Пикман, кушайте"
  },
  AvgVideoCaption_96010_Content_102 = {
    Text = "Рвите его плоть, режьте его сердце"
  },
  AvgVideoCaption_96010_Content_103 = {
