  },
  AvgVideoCaption_96010_Content_108 = {
    Text = "Так что, приятный ужин должен закончиться"
  },
  AvgVideoCaption_96010_Content_109 = {
    Text = "На этом фестивале духов в этом году мы точно увидим шедевр"
  },
  AvgVideoCaption_96010_Content_11 = {
    Text = "С вашего позволения, мистер Пикмен"
  },
  AvgVideoCaption_96010_Content_110 = {
    Text = "Добро пожаловать в город останков, будущий мастер"
  },
  AvgVideoCaption_96010_Content_111 = {
    Text = "Господин Пикман"
  },
  AvgVideoCaption_96010_Content_12 = {
    Text = "Твои прошедшие картины"
  },
  AvgVideoCaption_96010_Content_13 = {
    Text = "Все это банально в своём ограничении людскими предрассудками"
  },
  AvgVideoCaption_96010_Content_14 = {
    Text = "Это и есть причина, по которой я пригласил вас сюда"
