  AvgVideoCaption_96010_Content_17 = {
    Text = "Тело человека?"
  },
  AvgVideoCaption_96010_Content_18 = {Text = "Это…"},
  AvgVideoCaption_96010_Content_19 = {
    Text = "Ты чувствуешь это?"
  },
  AvgVideoCaption_96010_Content_2 = {
    Text = "Прошу присаживаться"
  },
  AvgVideoCaption_96010_Content_20 = {
    Text = "Аромат дуба, кедра и ветивера"
  },
  AvgVideoCaption_96010_Content_21 = {
    Text = "Он погружён в этот гроб три сотни лет"
  },
  AvgVideoCaption_96010_Content_22 = {
    Text = "Таким образом, он получил честь стать главным блюдом вечера"
  },
  AvgVideoCaption_96010_Content_23 = {
    Text = "Подготовка к необходимому приему пищи"
  },
  AvgVideoCaption_96010_Content_24 = {
    Text = "0.5-дюймовый след от ножа"
  },
  AvgVideoCaption_96010_Content_25 = {
    Text = "Отделите костное тело по хребту и костям"
  },
  AvgVideoCaption_96010_Content_26 = {
    Text = "Что ты делаешь... его внутренности..."
  },
  AvgVideoCaption_96010_Content_27 = {
    Text = "Черт возьми, я должен уйти отсюда"
  },
  AvgVideoCaption_96010_Content_28 = {
    Text = "Что вы делаете... отпустите меня"
  },
  AvgVideoCaption_96010_Content_29 = {
    Text = "Пожалуйста, потише, господин Художник"
  },
  AvgVideoCaption_96010_Content_3 = {
    Text = "Я слышал, что в поместье упыря можно увидеть истинное искусство……"
  },
  AvgVideoCaption_96010_Content_30 = {
    Text = "Ты потревожил дух этого ингредиента и мешаешь моему творчеству"
  },
  AvgVideoCaption_96010_Content_31 = {
    Text = "Я специально велел оставить его внутренности"
  },
  AvgVideoCaption_96010_Content_32 = {
    Text = "Внутренности сложны и грязны"
  },
  AvgVideoCaption_96010_Content_33 = {
    Text = "Но после готовки они возвышаются до самого благородного и интересного"
