  AvgVideoCaption_96010_Content_37 = {
    Text = "Я ищу вдохновение……"
  },
  AvgVideoCaption_96010_Content_38 = {
    Text = "Как поедание тела связано с искусством?"
  },
  AvgVideoCaption_96010_Content_39 = {
    Text = "Это поможет тебе охватить твоё творчество"
  },
  AvgVideoCaption_96010_Content_4 = {
    Text = "Я оставил всё от человеческого мира и пришёл сюда"
  },
  AvgVideoCaption_96010_Content_40 = {
    Text = "Понять трупоеда, стать трупоедом"
