  AvgVideoCaption_96010_Content_42 = {
    Text = "Ты всегда понимал истину творчества"
  },
  AvgVideoCaption_96010_Content_43 = {
    Text = "Так вот почему ты оставил человеческий мир и пришел в мой замок"
