  AvgVideoCaption_96010_Content_44 = {
    Text = "Да, но…"
  },
  AvgVideoCaption_96010_Content_45 = {
    Text = "Попробуй это, мистер Пикман"
  },
  AvgVideoCaption_96010_Content_46 = {
    Text = "Во имя искусства"
  },
  AvgVideoCaption_96010_Content_47 = {Text = "Это…"},
  AvgVideoCaption_96010_Content_48 = {
    Text = "Верно, господин Пикман"
  },
  AvgVideoCaption_96010_Content_49 = {
    Text = "Нашёптывая тебе на ухо"
  },
  AvgVideoCaption_96010_Content_5 = {
    Text = "А теперь этот обывательский ресторан"
  },
  AvgVideoCaption_96010_Content_50 = {
    Text = "Это поглощенные души"
  },
  AvgVideoCaption_96010_Content_51 = {
    Text = "Душа... душа?"
  },
  AvgVideoCaption_96010_Content_52 = {
    Text = "Люди часто описывают нас как низших падальщиков"
  },
  AvgVideoCaption_96010_Content_53 = {
    Text = "Но вурдалаки не жаждут гнилого мяса"
  },
  AvgVideoCaption_96010_Content_54 = {
    Text = "То, что действительно волнует нас, это душа под гнилым мясом"
  },
  AvgVideoCaption_96010_Content_55 = {
    Text = "Это те, кого погребли могилы, дорогие воспоминания"
  },
  AvgVideoCaption_96010_Content_56 = {
    Text = "Мистер Пикман, ваши дрожащие пальцы"
